-- Generated by `forge guide compile` from the pack's locales/frFR/ files. Do not edit: rebuild with that command.

local t = { guides = {} }
t.pack = {
	["Chapters on Polestar's Alliance route: the Westfall meeting point and 17 dungeon chapters, each offered once at the right moment, boss by boss, with the quests to take first."] = "Chapitres sur le parcours Alliance de Polestar : rendez-vous dans la Marche de l'Ouest et 17 chapitres de donjon, chacun proposé une fois au bon moment, boss par boss, quêtes à prendre avant.",
	["Group Alliance"] = "Groupe Alliance",
	["Group Alliance · dungeons"] = "Groupe Alliance · donjons",
}
t.guides["groupe-alliance/02-rendez-vous-hurlevent"] = (function() return {
		["Dungeons: a card offers each dungeon chapter of the group at the right moment of the route. The chapter opens in a tab of its own and the route comes back when it ends; /ga donjon shows the card again."] = "Donjons : une carte propose chaque chapitre de donjon du groupe au bon moment du parcours. Le chapitre s'ouvre dans son propre onglet et le parcours revient à la fin ; /ga donjon remontre la carte.",
		["Group · Meeting in {zone:1436}"] = "Groupe · Rendez-vous dans la {zone:1436}",
		["Polestar's group tools: the party panel (/polestar party) shows each friend's guide, step and level; its \"Sync to my guide\" button asks the others to come to your step, and each one accepts or declines. The option \"Wait for the group\" holds a hand-in until the friends in the zone are ready. Share a quest from the quest log: click it, then Share."] = "Les outils de groupe de Polestar : le panneau de groupe (/polestar party) montre le guide, l'étape et le niveau de chaque ami ; son bouton « Synchro sur mon guide » propose aux autres de rejoindre son étape, et chacun accepte ou refuse. Le réglage « Attendre le groupe » retient un rendu tant que les amis de la zone ne sont pas prêts. Partager une quête depuis le journal : clic sur la quête, puis Partager.",
		["Polestar's route brings every race to {zone:1436}, each at its own level: Humans at about 11, Dwarves and Gnomes at about 14, Night Elves and the Skyborne (from Zephras Isle) at about 15. Whoever arrives first goes on: quests already handed in tick themselves for the others, and a friend ahead helps with their quests when you play together. Group XP stays good within about 4 levels."] = "Le parcours de Polestar amène chaque race en {zone:1436}, chacune à son niveau : les humains vers 11, les nains et les gnomes vers 14, les elfes de la nuit et les Éolides (depuis Zephras) vers 15. Le premier arrivé continue : les quêtes déjà rendues se cochent seules pour les autres, et un ami en avance aide aux quêtes des autres quand le groupe joue ensemble. L'XP de groupe reste bonne jusqu'à environ 4 niveaux d'écart.",
		["Read: tick this line to close this tab and go back to the route"] = "Lu : cocher cette ligne pour fermer cet onglet et revenir au parcours",
} end)()
t.guides["groupe-alliance/04-salle-des-thanes"] = (function() return {
		["Anvilmar's Rest: {npc:261306}"] = "Le Repos d'Anvilmar : {npc:261306}",
		["Back in the halls, a pack of four {object:147516} dwarves stands between two kegs: shoot the kegs from afar first. {npc:261311}, a stone golem, walks the hallway after it: pull him away from the others and tank him with his back to a wall, as he knocks back and charges whoever stands close."] = "De retour dans les salles, un groupe de quatre nains {object:147516} se tient entre deux tonneaux : tirer d'abord sur les tonneaux de loin. {npc:261311}, un golem de pierre, arpente le couloir qui suit : l'attirer à l'écart des autres et le tanker dos à un mur, car il repousse et charge ceux qui sont près de lui.",
		["Before entering the Hall of Thanes"] = "Avant d'entrer dans la Salle des Thanes",
		["Dungeon · The Hall of Thanes (14-19)"] = "Donjon · La Salle des Thanes (14-19)",
		["In the log: {quest:96403} ({npc:265003}) and {quest:96394} ({npc:264943}); {quest:96393} for whoever took it from {npc:264936}. Share each quest with the group: click it in the quest log, then Share."] = "Dans le journal : {quest:96403} ({npc:265003}) et {quest:96394} ({npc:264943}) ; {quest:96393} pour qui l'a prise chez {npc:264936}. Partager chaque quête avec le groupe : clic sur la quête dans le journal, puis Partager.",
		["Its name differs between sources (Infurnus in the dungeon journal, Magmatus in the guides): the only fire elemental boss of the dungeon."] = "Son nom change selon les sources (Infurnus dans le journal des donjons, Magmatus dans les guides) : le seul boss élémentaire de feu du donjon.",
		["King Magni: {quest:96393}"] = "Le roi Magni : {quest:96393}",
		["North over the bridge of the Lesser Stone Golems to the round last room. Clear it before the pull: {npc:261319} fears the whole group and whatever is left joins in. Kill his two Lesser Stone Golems first. Each player on {quest:96393} loots the head. Behind one of the vault doors of the room, the {item:281030}: each player clicks it for their own quest."] = "Vers le nord par le pont des golems de pierre inférieurs jusqu'à la dernière salle, ronde. La nettoyer avant d'attaquer : {npc:261319} fait fuir de peur tout le groupe et ce qui reste se joint au combat. Tuer d'abord ses deux golems de pierre inférieurs. Chaque joueur qui a {quest:96393} ramasse la tête. Derrière l'une des portes de caveau de la salle, le {item:281030} : chaque joueur clique dessus pour sa propre quête.",
		["South-east out of Anvilmar's Rest: {object:147516} dwarves from here on. Bloodhound Runts leave a disease that makes their target take more damage (Stoneform or a poultice clears it); Engineers throw dynamite; Summoners call fire elementals: interrupt them. Ranged players can shoot the kegs of blasting powder to hit the packs around them. In the natural cavern, the fire elemental boss burns everyone near him: kill the {npc:263438} beside him first, ranged players keep away, and the healer watches the melee too."] = "Sortie au sud-est du Repos d'Anvilmar : des nains {object:147516} à partir d'ici. Les avortons de limier laissent une maladie qui fait subir plus de dégâts (Forme de pierre ou un cataplasme l'enlève) ; les ingénieurs lancent de la dynamite ; les invocateurs appellent des élémentaires de feu : les interrompre. Les joueurs à distance peuvent tirer sur les tonneaux de poudre explosive pour toucher les groupes autour. Dans la caverne naturelle, le boss élémentaire de feu brûle tous ceux qui l'entourent : tuer d'abord l'{npc:263438} à côté de lui, les joueurs à distance restent loin, et le soigneur surveille aussi les joueurs au corps à corps.",
		["The Hall of Thanes"] = "La salle des Thanes",
		["The Hall of Thanes: a 5-player Forever dungeon under {zone:1455}, levels 13 to 20 in the group finder: at 15 or more it goes well. Its quests are taken in {zone:1455}, a few steps from its door, and handed in there."] = "La Salle des Thanes : un donjon de Forever pour 5 joueurs sous {zone:1455}, niveaux 13 à 20 dans la recherche de groupe : à 15 ou plus, il passe bien. Ses quêtes se prennent à {zone:1455}, à quelques pas de sa porte, et s'y rendent.",
		["The Hall of Thanes: along the way"] = "La Salle des Thanes : en chemin",
		["The Reliquary of Kings: {npc:261319}"] = "Le Reliquaire des rois : {npc:261319}",
		["The fire elemental is down"] = "L'élémentaire de feu est tombé",
		["The fire elemental of the cavern"] = "L'élémentaire de feu de la caverne",
		["The ghosts of the first chambers are {npc:264943}'s: Enraged Apparitions and Tormented Souls. The Dwarven Heirlooms lie all over the dungeon, many on candle-lit ledges of the corridors; the vaults of the last room hold enough for everyone, so nobody needs to race for them."] = "Les fantômes des premières salles sont pour {npc:264943} : apparitions enragées et âmes tourmentées. Les héritages nains sont partout dans le donjon, beaucoup sur des corniches éclairées de bougies dans les couloirs ; les caveaux de la dernière salle en contiennent assez pour tout le monde, inutile de se les disputer.",
		["The {npc:265002} waits in the chamber west of the entrance: her quest is the first boss. {npc:261306} walks round the great tomb of the next room: clear the ghosts around it first. His Anvilmar's Curse slows the tank's attacks and spells for a long time: a Mage or a Druid can remove it. His Mind Blast can be interrupted."] = "{npc:265002} attend dans la salle à l'ouest de l'entrée : sa quête est le premier boss. {npc:261306} fait le tour du grand tombeau de la salle suivante : nettoyer d'abord les fantômes autour. Sa Malédiction d'Anvilmar ralentit longtemps les attaques et les sorts du tank : un mage ou un druide peut la retirer. Son Attaque mentale peut être interrompue.",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["{item:281030}, behind a vault door of the room"] = "{item:281030}, derrière une porte de caveau de la salle",
		["{npc:264936}: {quest:96393} (optional)"] = "{npc:264936} : {quest:96393} (facultatif)",
		["{npc:265002}, on the way back too"] = "{npc:265002}, aussi au retour",
		["{zone:1453}: the tram to {zone:1455}"] = "{zone:1453} : le tram pour {zone:1455}",
		["{zone:1455} rewards"] = "Récompenses à {zone:1455}",
		["{zone:1455}: {npc:265003} and {npc:264943}"] = "{zone:1455} : {npc:265003} et {npc:264943}",
} end)()
t.guides["groupe-alliance/06-ruines-de-lordaeron"] = (function() return {
		["Auberdine: the boat to Southshore"] = "Auberdine : le bateau pour Austrivage",
		["Back to the entrance on the way out: {npc:265701} takes the Baron's head."] = "Retour à l'entrée en sortant : {npc:265701} prend la tête du Baron.",
		["Back to the route: click its tab now. This tab stays open for the three {zone:1453} rewards: the route reaches {zone:1453} at about 20, by the Deeprun Tram, and Polestar lists the hand-ins once there; this tab closes when they are in."] = "Retour au parcours : cliquer maintenant sur son onglet. Cet onglet reste ouvert pour les trois récompenses de {zone:1453} : le parcours arrive à {zone:1453} vers 20, par le Tram des profondeurs, et Polestar y affiche les rendus ; cet onglet se ferme une fois les quêtes rendues.",
		["Blood-stained letter, by {npc:250657}: each player clicks their own"] = "Lettre tachée de sang, près de {npc:250657} : chaque joueur clique la sienne",
		["Boat to Southshore"] = "Bateau pour Austrivage",
		["Dungeon · Ruins of Lordaeron (17-22)"] = "Donjon · Ruines de Lordaeron (17-22)",
		["Flesh Golems hit hard and knock you into other packs; ghouls come in threes and fours. Viktor is optional: light the chimney of the ruined house in the south-west, survive 4 to 6 waves (leave the last enemy of each wave alive a moment so casters can drink), then he jumps out. Short group? Skip him."] = "Les golems de chair frappent fort et projettent dans d'autres groupes ; les goules viennent par trois ou quatre. Viktor est facultatif : allumer la cheminée de la maison en ruine au sud-ouest, tenir 4 à 6 vagues (laisser vivre un moment le dernier ennemi de chaque vague pour que les lanceurs de sorts boivent), puis il surgit. Groupe réduit ? Le laisser.",
		["For {npc:228} in Darkshire"] = "Pour {npc:228}, à Sombre-Comté",
		["Keep 5 free quest log slots. Horde land past Southshore: travel together."] = "Garder 5 places libres dans le journal. Terre de la Horde passé Austrivage : voyager ensemble.",
		["Lordamere Overlook: {npc:256035} (optional)"] = "Surplomb de Lordamere : {npc:256035} (facultatif)",
		["Market Street: {npc:250631} (optional)"] = "Rue du Marché : {npc:250631} (facultatif)",
		["Off the boat, the flight master stands by the inn: take the flight path, then sell and repair."] = "En descendant du bateau, le maître de vol se tient près de l'auberge : prendre le point de vol, puis vendre et réparer.",
		["On the left just after the portal. The bosses can be done in any order. Any undead may drop a {quest:95195}: right-click it, then keep looting them, there are plenty for everyone."] = "À gauche juste après le portail. Les boss se font dans n'importe quel ordre. N'importe quel mort-vivant peut lâcher un {quest:95195} : clic droit dessus, puis continuer à les ramasser, il y en a pour tout le monde.",
		["One crest per run, at a random spot with no mark on the minimap: the top of the east tower (left of the top floor doors), the banshee crypt door before {npc:250660}, the top of the west tower, the foot of the north-west tower by the double stairs, or the wall of {npc:256097}'s gazebo (nearly invisible: hover the wall)."] = "Un seul écusson par passage, à une place au hasard, sans marque sur la minicarte : le haut de la tour est (à gauche des portes du dernier étage), la porte de crypte à banshee devant {npc:250660}, le haut de la tour ouest, le pied de la tour nord-ouest près du double escalier, ou le mur du kiosque de {npc:256097} (presque invisible : passer la souris sur le mur).",
		["Right from the entrance. Skeletons and banshees guard him; the banshees silence, so stun the packs. His head drops for everyone on the quest. The crypt door with a banshee in front of him is one of the Crest's spots."] = "À droite depuis l'entrée. Squelettes et banshees le gardent ; les banshees réduisent au silence, étourdir les groupes. Sa tête tombe pour chaque joueur qui a la quête. La porte de crypte gardée par une banshee devant lui est une des places possibles de l'écusson.",
		["Ruins of Lordaeron"] = "Ruines de Lordaeron",
		["Ruins of Lordaeron entrance"] = "Entrée des Ruines de Lordaeron",
		["Share each quest with the group: click it in the quest log, then Share."] = "Partager chaque quête avec le groupe : clic sur la quête dans le journal, puis Partager.",
		["Southshore"] = "Austrivage",
		["The Crest: clicked, or not found"] = "L'écusson : cliqué, ou pas trouvé",
		["The graveyard at the back. His one spell, Flamestrike, lands where the tank stood when he began it: step out at once, or stun him to stop it. The rare {npc:255699} is friendly to the Alliance: leave him be."] = "Le cimetière du fond. Son seul sort, Choc de flammes, tombe là où se tenait le tank au début de l'incantation : en sortir tout de suite, ou l'étourdir pour l'arrêter. Le rare {npc:255699} est amical pour l'Alliance : le laisser.",
		["The spider wing, King's Alley. {npc:250483} patrols with two spiders: kill them first and cleanse Leech Poison off the tank. Spider packs patrol too: pull with care."] = "L'aile des araignées, allée du Roi. {npc:250483} patrouille avec deux araignées : les tuer d'abord et dissiper le poison sur le tank. Des groupes d'araignées patrouillent aussi : tirer avec prudence.",
		["The statue with green eyes starts 3 waves, and the skeleton mage in the south corridor must die too; then {npc:250631}: Frost Nova, slows melee, drains the tank. Optional. The top of the west tower next to it is one of the Crest's spots."] = "La statue aux yeux verts lance 3 vagues, et le mage squelette du couloir sud doit mourir aussi ; puis {npc:250631} : Nova de givre, ralentit le corps à corps, draine le tank. Facultatif. Le haut de la tour ouest, à côté, est une des places possibles de l'écusson.",
		["The undead troll patrolling the north-west: a simple fight, just wait out his short Anti-Magic Shield."] = "Le troll mort-vivant qui patrouille au nord-ouest : un combat simple, attendre juste la fin de son court bouclier anti-magie.",
		["The {quest:95189}"] = "{quest:95189}",
		["{npc:250631}, or skipped"] = "{npc:250631}, ou laissé",
		["{npc:256035}, or skipped"] = "{npc:256035}, ou laissé",
		["{npc:265701}, by the entrance"] = "{npc:265701}, près de l'entrée",
		["{npc:466} stands at the city gate, {npc:14450} in the orphanage, {npc:15991} in the keep. The Matron gives the next letter, for Darkshire in {zone:1431}: the route stops there at about 25."] = "{npc:466} se tient à la porte de la ville, {npc:14450} à l'orphelinat, {npc:15991} dans le donjon. La matrone donne la lettre suivante, pour Sombre-Comté dans le {zone:1431} : le parcours s'y arrête vers 25.",
		["{quest:95189}: each player clicks it"] = "{quest:95189} : chaque joueur clique dessus",
		["{quest:95195}, from any undead: right-click it"] = "{quest:95195}, sur n'importe quel mort-vivant : clic droit dessus",
		["{quest:95195}, from the undead all run long"] = "{quest:95195}, sur les morts-vivants pendant tout le donjon",
		["{zone:1453} rewards"] = "Récompenses à {zone:1453}",
} end)()
t.guides["groupe-alliance/07b-mortemines"] = (function() return {
		["Alone: around 20-21 for the cards, 23 for the Foreman. Two players: fine at 19-20. The cards drop rarely and each player loots their own: skip them if time runs short."] = "Seul : vers 20-21 pour les cartes, 23 pour le contremaître. À deux : faisable vers 19-20. Les cartes tombent rarement et chacun ramasse les siennes : les laisser si le temps manque.",
		["Before entering the Deadmines"] = "Avant d'entrer dans les Mortemines",
		["Captain's cabin, top of the ship. Two Blackguards join at the pull, two more at half health: a stun at 51 to 55% skips the second pair. Everyone on the quest loots their own head and their own letter."] = "Cabine du capitaine, en haut du bateau. Deux canailles le rejoignent au début, deux autres à mi-vie : un étourdissement vers 51 à 55 % évite la seconde paire. Chaque joueur qui a la quête ramasse sa tête et sa lettre.",
		["Clear every {npc:641} of the lumber room first, pulling them back to the previous room: the Shredder's Terrify sends you running into them. {npc:643} jumps out when it breaks; he disarms."] = "Vider d'abord chaque {npc:641} de la scierie, en les tirant dans la salle précédente : la Terreur du broyeur fait fuir droit sur eux. {npc:643} saute dehors quand la machine casse ; il désarme.",
		["Cookie, on the lower deck, is optional: interrupt his healing cast. Do not hearth: leave by the back, along the coast."] = "Macaron, sur le pont inférieur, est facultatif : interrompre son soin. Pas de pierre de foyer : sortir par l'arrière, le long de la côte.",
		["Dungeon · The Deadmines (18-24)"] = "Donjon · Les Mortemines (18-24)",
		["Fly to {zone:1453} for two more quests of the mine; train while you are here. {npc:656} stands in the tavern of the {object:28027}, {npc:6579} nearby."] = "Vol vers {zone:1453} pour deux autres quêtes de la mine ; passer chez le maître de classe au passage. {npc:656} est dans la taverne du {object:28027}, {npc:6579} tout près.",
		["Goblin Engineers and Craftsmen summon golems: kill or stun the goblin, the golem goes with it. {npc:1763} has an Engineer at his side."] = "Les ingénieurs et artisans gobelins invoquent des golems : tuer ou étourdir le gobelin, le golem disparaît avec lui. {npc:1763} a un ingénieur à ses côtés.",
		["Group of 5, level 18 or more. Pull the two Watchmen away from {npc:644} first, and turn around after every boss: patrols come from behind. {npc:3586}, a rare, may stand in the small tunnel on the left after him: kill his miners first."] = "Groupe de 5, niveau 18 ou plus. Éloigner d'abord les deux guetteurs de {npc:644}, et se retourner après chaque boss : des patrouilles arrivent par derrière. {npc:3586}, un rare, peut se tenir dans le petit tunnel à gauche après lui : tuer ses mineurs d'abord.",
		["In the cove: two stealthed Defias Blackguards join him by the walkway, kill them before he reaches 66%. At 66% and 33% he stuns the whole group for a few seconds and changes weapons: keep the tank's health up before each."] = "Dans la crique : deux canailles défias camouflées le rejoignent près de la passerelle, les tuer avant qu'il arrive à 66 %. À 66 % et 33 %, il étourdit tout le groupe quelques secondes et change d'arme : garder le tank plein de vie avant chaque fois.",
		["Keep 6 free quest log slots. Everyone takes the quests at their own pace; meet at the Moonbrook entrance for the run."] = "Garder 6 places libres dans le journal. Chacun prend les quêtes à son rythme ; rendez-vous à l'entrée de Ruisselune pour le donjon.",
		["Moonbrook's smithy hides the mine. Before the portal, the purple area of the minimap holds elite undead miners in pairs: the Miners' Union Cards drop there, not inside, and {npc:626} stands at the far end with a linked add."] = "La forge de Ruisselune cache la mine. Avant le portail, la zone violette de la minicarte abrite des mineurs morts-vivants élites, par paires : les cartes du syndicat des mineurs tombent là, pas dans l'instance, et {npc:626} se tient au bout, avec un garde lié.",
		["Oh Brother..."] = "Ah, mon frère...",
		["On the ship. Crowd-control the Squallshaper, kill the Companion, then the Pirate, then Greenskin facing away from the group (Cleave)."] = "Sur le bateau. Neutraliser le façonneur de grains, tuer le compagnon, puis le pirate, puis Peau-Verte tourné dos au groupe (Enchaînement).",
		["Paladins: {item:6994}"] = "Paladins : {item:6994}",
		["Share each quest with the group before going in: click it in the quest log, then Share."] = "Partager chaque quête avec le groupe avant d'entrer : clic sur la quête dans le journal, puis Partager.",
		["The Deadmines"] = "Les Mortemines",
		["The Goblin Woodcarvers of the lumber room drop the {item:6994} for {quest:1654} ({npc:6181}, {zone:1455}): one is enough."] = "Les Sculpteurs gobelins de la salle du bois lâchent le {item:6994} pour {quest:1654} ({npc:6181}, {zone:1455}) : un seul suffit.",
		["The cannon door"] = "La porte du canon",
		["The cannon door is open"] = "La porte du canon est ouverte",
		["The mine outside the portal"] = "La mine avant le portail",
		["The {item:5397} barrel sits in the alcove on the right just before the cannon. Fire the cannon, then step back: a patrol of elites comes out through the broken door. A Rogue can pick the lock instead."] = "Le tonneau de {item:5397} est dans l'alcôve à droite juste avant le canon. Tirer, puis reculer : une patrouille d'élites sort par la porte brisée. Un voleur peut crocheter la serrure à la place.",
		["{item:1875}: {npc:626}, elite"] = "{item:1875} : {npc:626}, élite",
		["{item:1894}: Undead Excavators and Dynamiters, elite"] = "{item:1894} : excavateurs et dynamiteurs morts-vivants, élites",
		["{item:2874}, on VanCleef: right-click it, it opens the Stockade chain"] = "{item:2874}, sur VanCleef : clic droit dessus, elle ouvre la suite vers la Prison",
		["{item:915}: any Defias"] = "{item:915} : n'importe quel Défias",
		["{npc:1646}: {quest:389}, for the Stockade chapter ({npc:1719})"] = "{npc:1646} : {quest:389}, pour le chapitre de la Prison ({npc:1719})",
		["{npc:1763}'s foundry"] = "La fonderie de {npc:1763}",
		["{npc:642} and {npc:643}"] = "{npc:642} et {npc:643}",
		["{npc:656} is in the tavern of the {object:28027}. Last stop of the chapter: the route's own guide comes back once these are handed in."] = "{npc:656} est dans la taverne de {object:28027}. Dernier arrêt du chapitre : le guide du parcours revient une fois ces quêtes rendues.",
		["{npc:6579} stands by the tram in the {object:28027}."] = "{npc:6579} se tient près du tram, dans {object:28027}.",
		["{npc:820}, at the top of the tower: {quest:214}"] = "{npc:820}, en haut de la tour : {quest:214}",
		["{npc:820}, top of the tower"] = "{npc:820}, en haut de la tour",
		["{quest:214} drop from Defias all through the dungeon."] = "Les {quest:214} tombent sur les Défias dans tout le donjon.",
		["{zone:1453} rewards"] = "Récompenses à {zone:1453}",
		["{zone:1453}: the miners' quests"] = "{zone:1453} : les quêtes des mineurs",
} end)()
t.guides["groupe-alliance/08b-prison"] = (function() return {
		["At the junction, type /target {npc:1720}: if a frame shows, the rare elite (26) is in a cell nearby, with the best loot of the dungeon."] = "Au croisement, taper /target {npc:1720} : si un cadre s'affiche, l'élite rare (26) est dans une cellule proche, avec le meilleur butin du donjon.",
		["Cells line both sides, 3 or 4 elites each, and runners flee into the next cell for help: stop them or clear each cell as you pass. {npc:1696} hides in a side cell of this corridor (often first on the right or second on the left); a patrol walks between the two wings."] = "Des cellules des deux côtés, 3 ou 4 élites chacune, et les fuyards courent chercher de l'aide dans la cellule voisine : les arrêter ou vider chaque cellule au passage. {npc:1696} se cache dans une cellule de ce couloir (souvent la 1re à droite ou la 2e à gauche) ; une patrouille circule entre les deux ailes.",
		["Clara's apples"] = "Les pommes de Clara",
		["Darkshire: {npc:270}"] = "Sombre-Comté : {npc:270}",
		["Defias Prisoners, Convicts and Insurgents"] = "Prisonniers, détenus et insurgés défias",
		["Dungeon · The Stockade (25-31)"] = "Donjon · La Prison (25-31)",
		["Enter the Stockade"] = "Entrer dans la Prison",
		["Finish the clear"] = "Finir le nettoyage",
		["Fly to Lakeshire and back: a few minutes for the biggest reward of the prison."] = "Aller-retour en vol à Comté-du-Lac : quelques minutes pour la plus grosse récompense de la Prison.",
		["In the log before going in: Quell the Uprising and {quest:391} ({npc:1719}), {quest:388} ({npc:1721}). Share each quest with the group: click it in the quest log, then Share."] = "Dans le journal avant d'entrer : Mater la révolte (Quell the Uprising) et {quest:391} ({npc:1719}), {quest:388} ({npc:1721}). Partager chaque quête avec le groupe : clic sur la quête dans le journal, puis Partager.",
		["Keep 6 free quest log slots. Everyone takes the quests on their own; meet at the prison gate for the run."] = "Garder 6 places libres dans le journal. Chacun prend les quêtes de son côté ; rendez-vous à la porte de la prison pour le donjon.",
		["Lakeshire: {npc:859}"] = "Comté-du-Lac : {npc:859}",
		["Last stop of the chapter: the route's own guide comes back once this is handed in."] = "Dernier arrêt du chapitre : le guide du parcours revient une fois cette quête rendue.",
		["Left at the junction, to the small hall at the end. Clear every room around it first: his Intimidating Shout fears the group into fresh packs. He runs at low health: stop him."] = "À gauche au croisement, jusqu'à la petite salle du bout. Vider d'abord chaque pièce autour : son cri d'intimidation fait fuir le groupe vers des groupes frais. Il fuit à faible vie : l'arrêter.",
		["One Convict short after a full clear? Wait a few minutes at the entrance for the respawn rather than resetting. Two chests, one in each wing. Leaving through the portal drops whatever chases you."] = "Un forçat manquant après un tour complet ? Attendre quelques minutes la réapparition à l'entrée plutôt que réinitialiser. Deux coffres, un par aile. Ressortir par le portail fait lâcher prise à tout poursuivant.",
		["Overhear Lescovar and {npc:1755} in the garden, then kill both"] = "Écouter Lescovar et {npc:1755} dans le jardin, puis les tuer tous les deux",
		["Red Wool Bandanas and the prisoners for Quell the Uprising come from every Defias."] = "Les bandanas en laine rouge et les prisonniers de Mater la révolte (Quell the Uprising) viennent de tous les Défias.",
		["Right at the junction. {npc:1666} sits in a cell (second on the left); {npc:1717} comes with two linked Insurgents and casts Chain Lightning: crowd-control an add and spread out. {npc:1716} waits at the very end: he hits one target hard and his Smoke Bomb stuns, so keep the tank topped up."] = "À droite au croisement. {npc:1666} est dans une cellule (la 2e à gauche) ; {npc:1717} vient avec deux insurgés liés et lance Chaîne d'éclairs : neutraliser un des deux et s'écarter. {npc:1716} attend tout au bout : il frappe fort une seule cible et sa bombe fumigène étourdit, garder le tank plein de vie.",
		["The Stockade"] = "La Prison",
		["The Stockade, {zone:1453}'s prison taken over by rioting Defias, is a group dungeon in the canals between the {object:2101} and {object:2100}, levels 24 to 32 in the group finder: at 26 or more it goes well. {npc:1719} keeps its gate, south of the {object:2098}."] = "La Prison de {zone:1453}, prise par des Défias en révolte, est un donjon de groupe dans les canaux entre le {object:2101} et la {object:2100}, niveaux 24 à 32 dans la recherche de groupe : à 26 ou plus, il passe bien. {npc:1719} garde sa porte, au sud de la {object:2098}.",
		["The bowl of apples sits on the table of the farmhouse just outside the {zone:1453} gate, south-west of the road. {item:4306}: from your bags, humanoids or the Auction House."] = "Le bol de pommes repose sur la table de la ferme juste à l'extérieur de la porte de {zone:1453}, au sud-ouest de la route. {item:4306} : dans les sacs, sur des humanoïdes ou à l'hôtel des ventes.",
		["The east wing: Kam, {npc:1717} and {npc:1716}"] = "L'aile est : Kam, {npc:1717} et {npc:1716}",
		["The end of the Defias story follows, all in {zone:1453} and at the farm by its gate: about 8,000 XP and the {item:2933}, a ring, at the end; its last fight is better with the group. Short on time? Skip it: {npc:1721} in {object:2100} ends the chapter."] = "La fin de l'histoire des Défias suit, toute à {zone:1453} et à la ferme près de sa porte : environ 8 000 XP et le {item:2933}, une bague, à la fin ; son dernier combat passe mieux en groupe. Peu de temps ? La passer : {npc:1721}, dans {object:2100}, termine le chapitre.",
		["The entry corridor and Targorr"] = "Le couloir d'entrée et Targorr",
		["The gate is by {npc:1719}, at the top of the stairs on the canal. Group of 5 at 24 to 29, or 3 at 26 to 29. Every prisoner is elite (23 to 26); the Defias Prisoners disarm, so the tank builds threat before anyone hits."] = "La porte est près de {npc:1719}, en haut de l'escalier sur le canal. Groupe de 5 de 24 à 29, ou de 3 de 26 à 29. Tous les prisonniers sont élites (23 à 26) ; les prisonniers défias désarment, donc le tank prend la menace avant que les autres frappent.",
		["The west wing: {npc:1663}"] = "L'aile ouest : {npc:1663}",
		["What Comes Around, for whoever carries it"] = "Retour de bâton, pour qui la porte",
		["{item:2909}: any Defias inside"] = "{item:2909} : n'importe quel Défias à l'intérieur",
		["{item:2926}, elite 29"] = "{item:2926}, élite 29",
		["{item:3628}, elite 26. For {quest:377} ({npc:270}, Darkshire): the hand-in comes after the run."] = "{item:3628}, élite 26. Pour {quest:377} ({npc:270}, Sombre-Comté) : le rendu vient après le donjon.",
		["{item:3630}: {npc:1696}, elite 24. For What Comes Around ({npc:859}, Lakeshire): the hand-in comes after the run."] = "{item:3630} : {npc:1696}, élite 24. Pour Retour de bâton ({npc:859}, Comté-du-Lac) : le rendu vient après le donjon.",
		["{npc:1646}: {quest:389} (after the Deadmines)"] = "{npc:1646} : {quest:389} (après les Mortemines)",
		["{npc:1719}: {quest:389} (after the Deadmines)"] = "{npc:1719} : {quest:389} (après les Mortemines)",
		["{npc:1719}: {quest:392} (the end of the Defias story)"] = "{npc:1719} : {quest:392} (la fin de l'histoire des Défias)",
		["{npc:1721} stands in {object:2100}: the Red Wool Bandanas she wants drop from the Defias inside."] = "{npc:1721} se tient dans la {object:2100} : les bandanas en laine rouge qu'elle veut tombent des Défias de la prison.",
		["{npc:1749}, in the throne room of {object:2117}: {item:2933}"] = "{npc:1749}, dans la salle du trône de l'{object:2117} : {item:2933}",
		["{npc:1754} and {npc:1755} meet in the garden beside the keep: listen to them, then fight both, together. Better with the group."] = "{npc:1754} et {npc:1755} se retrouvent dans le jardin à côté du donjon : les écouter, puis les combattre tous les deux, ensemble. Mieux avec le groupe.",
		["{npc:270}, town hall"] = "{npc:270}, hôtel de ville",
		["{quest:377}, for whoever carries it"] = "{quest:377}, pour qui la porte",
		["{quest:392}: for {npc:1646}, {object:2098}"] = "{quest:392} : pour {npc:1646}, {object:2098}",
		["{zone:1453}: the end of the Defias story"] = "{zone:1453} : la fin de l'histoire des Défias",
} end)()
t.guides["groupe-alliance/10-site-de-fouilles"] = (function() return {
		["Back down the path: {npc:1244} is on the Green Belt."] = "Redescendre le chemin : {npc:1244} est sur la Ceinture verte.",
		["Clear around him first. Tendon Rip slows the tank hard and his Dust Storm makes everyone within 10 yards miss: casters stay out of it."] = "Nettoyer autour de lui d'abord. Il ralentit fortement le tank et sa tempête de poussière fait rater tout le monde à 10 mètres : les lanceurs de sorts restent en dehors.",
		["Daewyn stands near the burned dig camp, by the Dragonmaw."] = "Daewyn se tient près du camp de fouilles incendié, à côté des Gueule-de-dragon.",
		["Daewyn: {quest:95772}, from {npc:956} in Lakeshire"] = "Daewyn : {quest:95772}, de {npc:956} à Comté-du-Lac",
		["Dungeon · Excavation Site: {zone:1437} (27-34)"] = "Donjon · Site de fouilles : {zone:1437} (27-34)",
		["Excavation Site"] = "Site de fouilles",
		["Excavation Site entrance"] = "Entrée du site de fouilles",
		["Excavation Site: a 5-player Forever dungeon up the hill in the middle of the {zone:1437}, levels 26 to 33 in the group finder. Everything inside is elite and the last boss is 31: about 39,000 XP of quests and blue rewards."] = "Site de fouilles : un donjon de Forever pour 5 joueurs en haut de la colline au milieu des {zone:1437}, niveaux 26 à 33 dans la recherche de groupe. Tout est élite à l'intérieur et le dernier boss est de niveau 31 : environ 39 000 XP de quêtes et des récompenses bleues.",
		["From the meeting stone near Thelgen Rock, follow the mountain path up to the portal. A single graveyard serves the area: a wipe means a long walk back."] = "Depuis la pierre de rencontre près du rocher de Thelgen, suivre le sentier de montagne jusqu'au portail. Un seul cimetière dans le secteur : après un échec collectif, le retour à pied est long.",
		["In the log before going in: {quest:95647} ({npc:1480}), {quest:98815} ({npc:2094}), {quest:95646} ({npc:1244}). Share each quest with the group: click it in the quest log, then Share. Talk to {npc:262681} and Daewyn as soon as you find them inside: their follow-ups start with them."] = "Dans le journal avant d'entrer : {quest:95647} ({npc:1480}), {quest:98815} ({npc:2094}), {quest:95646} ({npc:1244}). Partager chaque quête avec le groupe : clic sur la quête dans le journal, puis Partager. Parler à {npc:262681} et à Daewyn dès qu'ils sont trouvés à l'intérieur : leurs suites commencent avec eux.",
		["In the small cave of the outdoor dig, west of the road."] = "Dans la petite grotte du chantier extérieur, à l'ouest de la route.",
		["Keep 6 free quest log slots. {npc:1480} is next to the inn, {npc:2094} near the docks."] = "Garder 6 places libres dans le journal. {npc:1480} est à côté de l'auberge, {npc:2094} près des quais.",
		["Lakeshire: {npc:956}"] = "Comté-du-Lac : {npc:956}",
		["Menethil rewards"] = "Récompenses à Menethil",
		["On the Green Belt, east of the road, on the way to the dig. He gives it once Blisters on the Land is done, which the route did."] = "Sur la Ceinture verte, à l'est de la route, sur le chemin des fouilles. Il la donne une fois Cloques sur la terre (Blisters on the Land) faite, ce que le parcours a fait.",
		["Only for whoever took {npc:956}'s quest in Lakeshire: the flight there and back. Otherwise straight on to {zone:1455}."] = "Seulement pour qui a pris la quête de {npc:956} à Comté-du-Lac : le vol aller et retour. Sinon, directement vers {zone:1455}.",
		["The last boss, level 31, woken by the Archival Panel on its right. Thunderclap slows everyone within 10 yards, and it knocks back and stuns the tank for 5 seconds: rotate stuns and slows, keep healing the tank, kite round the structures if need be. {npc:262681} waits on the wooden scaffold by its arena."] = "Le dernier boss, niveau 31, réveillé par le panneau d'archives à sa droite. Coup de tonnerre ralentit tout le monde à 10 mètres, et il projette et étourdit le tank 5 secondes : enchaîner étourdissements et ralentissements, soigner le tank, tourner autour des structures si besoin. {npc:262681} attend sur l'échafaudage en bois près de son arène.",
		["The most dangerous stretch: Thicket Lurkers leap out of the tall grass, and Matriarchs call more of them at low health. Keep to the narrow path, fight in the open, kill the others before a Matriarch. Shadetooth comes with two Thicket Hunters (dispel Infected Wound): crowd-control one, kill the other, and fight him in the crocodile cove on the left so his fear cannot throw anyone into the grass."] = "Le passage le plus dangereux : des raptors surgissent des hautes herbes, et les matriarches en appellent d'autres à faible vie. Rester sur le chemin étroit, combattre à découvert, tuer les autres avant une matriarche. Dent-Sombre vient avec deux chasseurs des fourrés (dissiper la blessure infectée) : en neutraliser un, tuer l'autre, et le combattre dans l'anse aux crocodiles à gauche pour que sa peur n'envoie personne dans les herbes.",
		["The tall grass and Shadetooth"] = "Les hautes herbes et Dent-Sombre",
		["The {npc:260808}"] = "{npc:260808}",
		["The {npc:260808} (elite 28) stands right of the Dragonmaw and the burned dig camp; only this one inside drops the rootcore, not the one outside the dungeon."] = "{npc:260808} (élite 28) se tient à droite des Gueules-de-dragon et du camp de fouilles brûlé ; seul celui de l'intérieur donne le cœur de racine, pas celui du dehors.",
		["{item:270180}: {npc:260808}, elite 28"] = "{item:270180} : {npc:260808}, élite 28",
		["{item:270865}, from the {npc:260326}: right-click it"] = "{item:270865}, sur {npc:260326} : clic droit dessus",
		["{item:284845}: Shadetooth and the Thicket raptors"] = "{item:284845} : Dent-Sombre et les raptors des fourrés",
		["{npc:1244}'s reward"] = "Récompense de {npc:1244}",
		["{npc:1480}: pick mana potions for casters"] = "{npc:1480} : potions de mana pour les lanceurs de sorts",
		["{npc:262681}, each player talks to him"] = "{npc:262681}, chaque joueur lui parle",
} end)()
t.guides["groupe-alliance/10b-gnomeregan"] = (function() return {
		["Back to {object:171524} by {zone:1455}'s gate."] = "Retour à {object:171524} par la porte de {zone:1455}.",
		["Collected all through the dungeon. {item:9309} (24 for {npc:6579}): the troggs, slimes, leper gnomes and machines. {quest:2924}: the Artificial Extrapolators, rectangular boxes on the floor all around the dungeon; each one vanishes once used, so a full group on the quest may have to search the whole dungeon. Every player with the quest loots their own."] = "À ramasser dans tout le donjon. {item:9309} (24 pour {npc:6579}) : les troggs, limons, gnomes lépreux et machines. {quest:2924} : les extrapolateurs (Artificial Extrapolator), des boîtes rectangulaires posées au sol partout dans le donjon ; chacune disparaît une fois utilisée, un groupe entier sur la quête doit donc parfois fouiller tout le donjon. Chaque joueur qui a la quête ramasse les siens.",
		["Dungeon · Gnomeregan (29-35)"] = "Donjon · Gnomeregan (29-35)",
		["Escort {npc:7850} back to the entrance"] = "Escorter {npc:7850} jusqu'à l'entrée",
		["Gnomeregan"] = "Gnomeregan",
		["Gnomeregan: a 5-player dungeon under {zone:1426}, levels 29 to 38 in the group finder, best from about 31; {npc:7800}, the last boss, is 34. {npc:6579} stands by the tram in the {object:28027}; every other giver is in {object:171524}, at the {zone:1455} end of the tram."] = "Gnomeregan : un donjon pour 5 joueurs sous {zone:1426}, niveaux 29 à 38 dans la recherche de groupe, idéal à partir de 31 environ ; {npc:7800}, le dernier boss, est de niveau 34. {npc:6579} se tient près du tram, dans {object:28027} ; tous les autres donneurs sont à {object:171524}, au bout du tram côté {zone:1455}.",
		["Gnomeregan: along the way"] = "Gnomeregan : en chemin",
		["Gnomeregan: before going in"] = "Gnomeregan : avant d'entrer",
		["Gnomeregan: the Engineering Labs"] = "Gnomeregan : les laboratoires d'ingénierie",
		["Gnomeregan: the Launch Bay"] = "Gnomeregan : la baie de lancement",
		["Gnomeregan: the Sparklematic, the Dormitory and the Clean Room"] = "Gnomeregan : le Sparklematic, le dortoir et la salle propre",
		["Gnomeregan: {npc:7800}"] = "Gnomeregan : {npc:7800}",
		["Group of 5, levels 29 to 38 in the group finder. Everything inside is elite and the mechanical foes hit hard."] = "Groupe de 5, niveaux 29 à 38 dans la recherche de groupe. Tout est élite à l'intérieur et les machines frappent fort.",
		["In the quest log before going in: {quest:2928} ({npc:6579}, {zone:1453}), {quest:2929}, {quest:2930} and {quest:2922} ({object:171524}), {quest:2926} (Ozzie, Kharanos). If you took them: {quest:2924} ({npc:6169}, {object:171524}), {quest:2962} (Ozzie, Kharanos). Bring the {item:9280} (or the White one), and 3 silver per {item:9308} you want to put in the {object:142487}."] = "Dans le journal avant d'entrer : {quest:2928} ({npc:6579}, {zone:1453}), {quest:2929}, {quest:2930} et {quest:2922} ({object:171524}), {quest:2926} (Ozzie, Kharanos). Si elles ont été prises : {quest:2924} ({npc:6169}, {object:171524}), {quest:2962} (Ozzie, Kharanos). Apporter la {item:9280} (ou la blanche), et 3 pièces d'argent par {item:9308} à mettre dans {object:142487}.",
		["Keep 9 free quest log slots. Every quest can be shared except {quest:2926} and its follow-up: each player takes those from Ozzie."] = "Garder 9 places libres dans le journal. Toutes les quêtes se partagent sauf {quest:2926} et sa suite : chaque joueur les prend chez Ozzie.",
		["Kharanos: Ozzie's next quest"] = "Kharanos : la quête suivante d'Ozzie",
		["Kharanos: {npc:1268}"] = "Kharanos : {npc:1268}",
		["Kharanos: {npc:1268} (Green Glow)"] = "Kharanos : {npc:1268} (lueur verte)",
		["Kharanos: {quest:2962} (optional detour)"] = "Kharanos : {quest:2962} (détour facultatif)",
		["Out of Gnomeregan and east to Kharanos, on the way back to {zone:1455}."] = "Sortir de Gnomeregan et aller à l'est jusqu'à Kharanos, sur le chemin de {zone:1455}.",
		["Out of Gnomeregan and east to Kharanos, within the two hours of the fallout."] = "Sortir de Gnomeregan et aller à l'est jusqu'à Kharanos, dans les deux heures des retombées.",
		["Ride out of {zone:1455} down to Kharanos. Ozzie hands you an {item:9283}."] = "Sortir de {zone:1455} et descendre à Kharanos. Ozzie remet {item:9283}.",
		["Share the quests with your group: click each in the quest log, then Share."] = "Partager les quêtes avec le groupe : clic sur chacune dans le journal, puis Partager.",
		["Take the Deeprun Tram to {zone:1453}: {npc:6579} is in the {object:28027}, by the tram. Last stop of the chapter: the route's own guide comes back once this is handed in."] = "Le Tram des profondeurs jusqu'à {zone:1453} : {npc:6579} est dans le {object:28027}, près du tram. Dernier arrêt du chapitre : le guide du parcours revient une fois la quête rendue.",
		["The City of Dalaran, a Forever dungeon in the {zone:1416}, has two {zone:1453} quests: about 18,800 XP. Its chapter comes once An Alarming Request is taken in Southshore (about 31). {npc:5502} is in the {object:2096}, {npc:5694} in the {object:2101} tower; the hand-ins wait for the route's next {zone:1453} stop."] = "La Cité de Dalaran, un donjon de Forever dans les {zone:1416}, a deux quêtes à {zone:1453} : environ 18 800 XP. Son chapitre vient une fois Une requête alarmante (An Alarming Request) prise à Austrivage (vers 31). {npc:5502} est dans le {object:2096}, {npc:5694} dans la tour du {object:2101} ; les rendus attendent le prochain arrêt du parcours à {zone:1453}.",
		["The Deeprun Tram to {zone:1455}, then {object:171524}, right by the tram."] = "Le Tram des profondeurs jusqu'à {zone:1455}, puis {object:171524}, juste à côté du tram.",
		["The Gnomeregan outskirts"] = "Les abords de Gnomeregan",
		["The last boss. Tank Thermaplugg (elite 34) in the middle of the room: his Walking Bombs then take longer to reach the group; ranged players kill them. They come faster at half health and faster still at 20 %. Overwhelmed? A button on the pillars around the room stops them for a while: give that job to one ranged player. After each knock-back his threat resets: let the tank take him back."] = "Le dernier boss. Tanker Thermaplugg (élite 34) au milieu de la salle : ses bombes ambulantes mettent alors plus de temps à atteindre le groupe ; les joueurs à distance les tuent. Elles arrivent plus vite à mi-vie, plus vite encore à 20 %. Débordés ? Un bouton sur les piliers autour de la salle les arrête un moment : confier ce rôle à un joueur à distance. Après chaque projection, sa menace repart de zéro : laisser le tank le reprendre.",
		["The {item:9365}, for {quest:2962}: the heavy phial, on a living irradiated slime or horror. The {quest:2945} drops from the Dark Iron Agents: right-click it."] = "La {item:9365}, pour {quest:2962} : la fiole lourde, sur un limon ou une horreur irradiés vivants. {quest:2945} tombe des agents Sombrefer : clic droit dessus.",
		["The {npc:6229} fights in the Engineering Labs; {object:142696}, on the lower level of that room, turns the Red card into the {item:9316}."] = "{npc:6229} combat dans les laboratoires d'ingénierie ; {object:142696}, au niveau inférieur de cette salle, change la carte rouge en {item:9316}.",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["{item:9277}: {npc:6231}, elite 26"] = "{item:9277} : {npc:6231}, élite 26",
		["{item:9279}: troggs and lepers"] = "{item:9279} : troggs et lépreux",
		["{item:9284}: the empty phial, on an {npc:6213}'s corpse"] = "{item:9284} : la fiole vide, sur le cadavre d'un {npc:6213}",
		["{item:9316}: the Red one, at {object:142696}"] = "{item:9316} : la rouge, dans {object:142696}",
		["{npc:1268}: then back to the portal"] = "{npc:1268} : puis retour au portail",
		["{npc:6169}: not offered without Mathiel's errand from {zone:1457}? Carry on without it"] = "{npc:6169} : pas proposée sans la course de Mathiel à {zone:1457} ? Continuer sans elle",
		["{npc:6569}: for {npc:1268} in Kharanos"] = "{npc:6569} : pour {npc:1268} à Kharanos",
		["{npc:7079}, in the Clean Room"] = "{npc:7079}, dans la salle propre",
		["{object:171524}: the hand-ins"] = "{object:171524} : les rendus",
		["{quest:2926} is done outside the dungeon, so it can be handed in now: back to Kharanos, then back to the portal, about two rides of a couple of minutes. Ozzie's next quest is done inside: use his {item:9364} on a LIVING irradiated slime or horror, and the fallout lasts two hours, enough for the run and the ride back. Not each player's cup of tea? Skip it: {quest:2926} is handed in after the run."] = "{quest:2926} se fait hors du donjon, elle peut donc se rendre maintenant : retour à Kharanos, puis retour au portail, deux trajets de quelques minutes. La quête suivante d'Ozzie se fait à l'intérieur : utiliser sa {item:9364} sur un limon ou une horreur irradiés VIVANTS ; les retombées durent deux heures, assez pour le donjon et le retour. Pas envie ? La passer : {quest:2926} se rend après le donjon.",
		["{quest:2947}: for {npc:6826} in {zone:1455}"] = "{quest:2947} : pour {npc:6826} à {zone:1455}",
		["{quest:2947}: {npc:6826} is in the {object:32362}. His next quest, Gnome Improvement, asks for a {item:2842} and a {item:1206}: not in the guide."] = "{quest:2947} : {npc:6826} est dans {object:32362}. Sa quête suivante, Gnome Improvement, demande {item:2842} et {item:1206} : hors du guide.",
		["{zone:1453}: two quests for the City of Dalaran (optional)"] = "{zone:1453} : deux quêtes pour la Cité de Dalaran (facultatif)",
		["{zone:1455}: Gnomeregan quests"] = "{zone:1455} : quêtes de Gnomeregan",
} end)()
t.guides["groupe-alliance/12-dalaran"] = (function() return {
		["Back out and right. Clear the landing, then everyone stands close behind the boss: its Focal Blast is a beam that turns round it, easy to walk round from up close."] = "Ressortir et prendre à droite. Nettoyer l'aire, puis tout le monde se place tout près, derrière le boss : sa Déflagration focalisée est un rayon qui tourne autour de lui, facile à contourner de près.",
		["Back out through the grate to Modera's camp. Last stop of the chapter: the route's own guide comes back once these are handed in. {quest:92456} and {quest:92489} go to {zone:1453}: Polestar lists them at the route's next {zone:1453} stop."] = "Ressortir par la grille jusqu'au camp de Modera. Dernier arrêt du chapitre : le guide du parcours revient une fois ces quêtes rendues. {quest:92456} et {quest:92489} se rendent à {zone:1453} : Polestar les affiche au prochain arrêt du parcours à {zone:1453}.",
		["City of Dalaran"] = "Cité de Dalaran",
		["City of Dalaran: a 5-player Forever dungeon in the {zone:1416}, levels 28 to 35 in the group finder. {npc:247264}'s errand leads to the {npc:269127}, by the city's wall: she gives the dungeon's two quests and the key of its sewers. His quest needs level 30."] = "Cité de Dalaran : un donjon de Forever pour 5 joueurs dans les {zone:1416}, niveaux 28 à 35 dans la recherche de groupe. La course de {npc:247264} mène à l'{npc:269127}, au pied du mur de la ville : elle donne les deux quêtes du donjon et la clé de ses égouts. La quête de l'émissaire demande le niveau 30.",
		["City of Dalaran: the sewer grate"] = "Cité de Dalaran : la grille des égouts",
		["Counter-clockwise to the north-east, by Antonidas's statue. Kill its two Mana Phantoms first. The Enigma polymorphs players and silences everyone close to it: ranged players keep away."] = "Dans le sens inverse des aiguilles d'une montre, vers le nord-est, près de la statue d'Antonidas. Tuer d'abord ses deux fantômes de mana. L'Énigme métamorphose des joueurs et réduit au silence tous ceux qui l'approchent : les joueurs à distance restent loin.",
		["Dungeon · City of Dalaran (30-38)"] = "Donjon · Cité de Dalaran (30-38)",
		["In the log before going in: {quest:92457} and {quest:92458} (Modera); {quest:92456} and {quest:92489} for whoever took them in {zone:1453}. Share each quest with the group: click it in the quest log, then Share."] = "Dans le journal avant d'entrer : {quest:92457} et {quest:92458} (Modera) ; {quest:92456} et {quest:92489} pour qui les a prises à {zone:1453}. Partager chaque quête avec le groupe : clic sur la quête dans le journal, puis Partager.",
		["Inside the Cantrips & Crows, cross the bridge and turn right: three large pipes lead to the Underbelly. Mindless Horrors fear (a Shaman's {npc:5913} helps), Kirin Tor Necromancers raise skeletons two at a time: the tank picks them up. {npc:247126}, in the summoning circle, is a stronger necromancer: clear the undead around him without pulling him, then a Shaman can purge his Unholy Frenzy."] = "Depuis la taverne (Cantrips & Crows), traverser le pont et tourner à droite : trois grosses canalisations mènent aux Entrailles (Underbelly). Les Horreurs décérébrées font fuir de peur (le {npc:5913} d'un chaman aide), les Nécromanciens du Kirin Tor lèvent des squelettes deux par deux : le tank les reprend. {npc:247126}, dans le cercle d'invocation, est un nécromancien plus fort : nettoyer les morts-vivants autour de lui sans l'attirer ; un chaman peut purger sa Frénésie impie.",
		["Into the middle of the city from the east: {npc:246708}, by the magic shield, lowers it. The {npc:246003} roots two players and drops burning fel timber under them: a Druid's shapeshift or a Paladin's Blessing of Freedom frees them. The {item:251983} for {quest:92456} is one of the big green bulbs of the square."] = "Vers le centre de la ville par l'est : {npc:246708}, près du bouclier magique, le baisse. L'{npc:246003} immobilise deux joueurs et fait tomber du bois gangrené en feu sous eux : un changement de forme de druide ou la Bénédiction de liberté d'un paladin les libère. La {item:251983} de {quest:92456} est l'un des gros bulbes verts de la place.",
		["Keep 4 free quest log slots."] = "Garder 4 places libres dans le journal de quêtes.",
		["Krasus' Landing: {npc:245999}"] = "Aire de Krasus : {npc:245999}",
		["Left from the sewers' exit. Clear every enemy of the hold first: they join the fight. The mana serpent drains the tank and hits the whole group now and then: heal through it."] = "À gauche en sortant des égouts. Nettoyer d'abord tous les ennemis du fort : ils rejoignent le combat. Le serpent de mana draine le tank et frappe tout le groupe de temps en temps : soigner sans relâche pendant ce temps.",
		["Magus Commerce Exchange: Unstable Sentry"] = "Comptoir des mages : la Sentinelle instable",
		["Modera's rewards"] = "Récompenses de Modera",
		["Out of the sewers, the arcane remnants are all over the streets: Seeking and Saturated Remnants for Modera. A {npc:247001} leaves a Mana Leak field when it dies (casters stand in it), Mana Fiends explode when they die (spread out), Mana Phantoms cast Mana Burn (interrupt it)."] = "Sortis des égouts, les résidus arcaniques sont partout dans les rues : les résidus chercheurs et saturés pour Modera. Un {npc:247001} laisse une zone de fuite de mana en mourant (les lanceurs de sorts s'y placent), les démons de mana explosent en mourant (s'écarter), les fantômes de mana lancent Brûlure de mana (l'interrompre).",
		["Path of Renewal: {npc:246016}"] = "Chemin du Renouveau : {npc:246016}",
		["Polestar's data also names the Alliance's own way in, a sewer pipe at {zone:1416} 14.7,63, which needs no key: not yet checked in game."] = "Les données de Polestar indiquent aussi l'entrée propre à l'Alliance, une conduite d'égout dans les {zone:1416} en 14.7,63, sans clé : pas encore vérifié en jeu.",
		["Runeweaver Square: {npc:246003}"] = "Place Tisserune : {npc:246003}",
		["Southshore: {npc:247264}"] = "Austrivage : {npc:247264}",
		["The Violet Citadel: {npc:246020}"] = "La Citadelle pourpre : {npc:246020}",
		["The sewers: {npc:247126}"] = "Les égouts : {npc:247126}",
		["The streets of Dalaran: along the way"] = "Les rues de Dalaran : en chemin",
		["The way in is the sewer grate in the city's western wall, by the lake, 30 yards from Modera's camp: the key opens it for the group."] = "L'entrée est la grille des égouts dans le mur ouest de la ville, au bord du lac, à 30 mètres du camp de Modera : la clé l'ouvre pour tout le groupe.",
		["The {npc:246297}: {npc:246008}"] = "{npc:246297} : {npc:246008}",
		["Unstable Sentry"] = "Sentinelle instable",
		["West through the city, in a nook of the market. Spread out; when it casts Malfunction, everyone but the tank steps well away."] = "Vers l'ouest à travers la ville, dans un recoin du marché. S'écarter les uns des autres ; quand elle lance Dysfonctionnement, tout le monde sauf le tank s'éloigne bien.",
		["{item:251983}: a green bulb of the square, for {quest:92456} ({npc:5502}, {zone:1453}, offered by the Gnomeregan chapter)"] = "{item:251983} : un bulbe vert de la place, pour {quest:92456} ({npc:5502}, {zone:1453}, proposée par le chapitre de Gnomeregan)",
		["{npc:246016}, for {quest:92489} ({npc:5694}, {zone:1453}, offered by the Gnomeregan chapter)"] = "{npc:246016}, pour {quest:92489} ({npc:5694}, {zone:1453}, proposée par le chapitre de Gnomeregan)",
		["{npc:246748} waits on the citadel's steps: talk to her for the portal to the Violet Chamber. A small room: ranged players spread out. Step out of the way of the slow bouncing orb (Bounding Mana). Out of mana, he polymorphs the whole group and casts Evocation: whoever can break free hits him then. Each player on {quest:92458} loots the {item:251961}."] = "{npc:246748} attend sur les marches de la citadelle : lui parler pour le portail vers la chambre Pourpre. Une petite salle : les joueurs à distance s'écartent. S'écarter de l'orbe lent qui rebondit (Mana bondissant). À court de mana, il métamorphose tout le groupe et lance Évocation : qui peut se libérer le frappe alors. Chaque joueur qui a {quest:92458} ramasse la {item:251961}.",
		["{quest:92458}: it brings the {item:277507}"] = "{quest:92458} : elle donne la {item:277507}",
		["{quest:92489}, for whoever took it"] = "{quest:92489}, pour qui l'a prise",
		["{zone:1453}'s two quests, for whoever took them"] = "Les deux quêtes de {zone:1453}, pour qui les a prises",
} end)()
t.guides["groupe-alliance/33-donjons-fin"] = (function() return {
		["Andorhal, the ruined city north of the camp: {npc:1852} (elite 61) stands in the middle of the town with his skeletons. Kill him, then click his phylactery for the scarab."] = "Andorhal, la ville en ruine au nord du camp : {npc:1852} (élite 61) se tient au milieu de la ville avec ses squelettes. Le tuer, puis cliquer sur son phylactère pour le scarabée.",
		["Andorhal: {npc:1852}"] = "Andorhal : {npc:1852}",
		["Arbington offers nothing? The first part of the key's chain (All Along the Watchtowers, Scholomance, {quest:5537}) is on the route in {zone:1422}; Polestar's Attunements page (guide menu, Attunements, {item:13704}, Guide me) leads through it."] = "Arbington ne propose rien ? La première partie de la chaîne de la clé (Tout au long des tours de guet, Scholomance, {quest:5537}) est sur le parcours, dans les {zone:1422} ; la page des accès de Polestar (menu du guide, Accès, {item:13704}, Me guider) y mène.",
		["Back into the same instance, through the cleared halls to the hatchlings' room: the torch on its south wall opens the way down to {npc:10503} (elite 61). She splits into illusions: mark her. Her corpse holds {quest:5515}."] = "Retour dans la même instance, par les salles déjà nettoyées, jusqu'à la salle des dragonnets : la torche de son mur sud ouvre le passage vers {npc:10503} (élite 61). Elle se dédouble en illusions : la marquer. Son corps porte {quest:5515}.",
		["Back to Chillwind Camp the long way. {npc:1852}, the next task, is a level 61 elite in Andorhal: the whole group goes."] = "Retour au camp du Noroît par le long trajet. {npc:1852}, la tâche suivante, est un élite de niveau 61 à Andorhal : tout le groupe y va.",
		["Back to Windsor's cell. Everyone hands in {quest:4282} before anyone starts {quest:4322}, with a free quest log slot. Windsor gets his gear back in the supply room clockwise from his cell, then frees his friends from the cells of the corridor round the Ring of the Law: open each cell when he asks, not before. Stay near him; he must not die. At the end he runs to the entrance and the quest is done. Failed? Abandon it, leave and reset the dungeon, then try again."] = "Retour à la cellule de Windsor. Tout le monde rend {quest:4282} avant que quiconque lance {quest:4322}, avec une place libre dans le journal. Windsor récupère son équipement dans la réserve, dans le sens des aiguilles d'une montre depuis sa cellule, puis libère ses amis des cellules du couloir qui fait le tour de l'arène : ouvrir chaque cellule quand il le demande, pas avant. Rester près de lui ; il ne doit pas mourir. À la fin, il court jusqu'à l'entrée et la quête est faite. Échec ? L'abandonner, sortir, réinitialiser le donjon et recommencer.",
		["Back to the central courtyard of Dire Maul: the western wing opens on its west wall, with the {item:18249}. Five pylons, great crystals, shield {npc:11496}'s prison: kill every {npc:11480} and {npc:11483} around a pylon to shut it down."] = "Retour à la cour centrale de Hache-Tripes : l'aile ouest s'ouvre sur son mur ouest, avec la {item:18249}. Cinq pylônes, de grands cristaux, protègent la prison de {npc:11496} : tuer toutes les {npc:11480} et tous les {npc:11483} autour d'un pylône pour l'éteindre.",
		["Back to the entrance: {npc:10799} walks around the first part of Hordemar City."] = "Retour à l'entrée : {npc:10799} se promène dans la première partie de la cité de Hordemar.",
		["Back to the {npc:14358} on the bridge of the Court of the Highborne. His next quest sends you to the {object:179517}, a chest under the ramp of the Athenaeum: take the one he offers."] = "Retour auprès de {npc:14358}, sur le pont de la cour des Bien-nés. Sa quête suivante envoie au {object:179517}, un coffre sous la rampe de l'Athénée : prendre celle qu'il propose.",
		["Back up through the Domicile to the Shrine: whoever carries {item:10999} places it on the {object:164689}. The {item:11000} is the reward. Then walk out the way you came: round the stands, through the Ring of the Law (its gates stay open) and the Detention Block."] = "Remonter par les logis jusqu'au sanctuaire : qui porte {item:10999} le pose sur {object:164689}. La {item:11000} est la récompense. Puis ressortir par où le groupe est venu : le tour des gradins, l'arène (ses grilles restent ouvertes) et la prison.",
		["Blackrock Depths"] = "Profondeurs de Rochenoire",
		["Blackrock Depths (dungeon, optional)"] = "Profondeurs de Rochenoire (donjon, facultatif)",
		["Blackrock Depths, first visit: before going in"] = "Profondeurs de Rochenoire, première visite : avant d'entrer",
		["Blackrock Depths, second visit: before going in"] = "Profondeurs de Rochenoire, deuxième visite : avant d'entrer",
		["Blackrock Depths, third visit: the Grim Guzzler"] = "Profondeurs de Rochenoire, troisième visite : la taverne",
		["Blackrock Depths: along the way"] = "Profondeurs de Rochenoire : en chemin",
		["Blackrock Depths: quests not done"] = "Profondeurs de Rochenoire : quêtes non finies",
		["Blackrock Depths: the {object:147516} dwarves' city under Blackrock Mountain, between the {zone:1427} and the {zone:1428}. Levels 52 to 60, bosses 51 to 59: easy for a group of 5 at 58 to 60; possible earlier at five (from about 54), difficult. The dungeon is huge: the guide splits it into three visits of one to two hours, with the quests given in {zone:1455}, Kharanos, the {zone:1428}, Lakeshire and {zone:1453}. Alone? Skip it."] = "Profondeurs de Rochenoire : la cité des nains {object:147516} sous le Mont Rochenoire, entre {zone:1427} et {zone:1428}. Niveaux 52 à 60, boss 51 à 59 : facile pour un groupe de 5 aux niveaux 58 à 60 ; possible plus tôt à cinq (vers 54), difficile. Le donjon est immense : le guide le découpe en trois visites d'une à deux heures, avec les quêtes données à {zone:1455}, Kharanos, dans {zone:1428}, à Comté-du-Lac et à {zone:1453}. Seul ? Le passer.",
		["Blackrock Mountain"] = "Mont Rochenoire",
		["Blackrock Mountain: {quest:4262}"] = "Mont Rochenoire : {quest:4262}",
		["Blackrock Spire"] = "Pic Rochenoire",
		["Caer Darrow: {npc:11216}"] = "Caer Darrow : {npc:11216}",
		["Caer Darrow: {npc:11936}"] = "Caer Darrow : {npc:11936}",
		["Capital Gardens and the Court of the Highborne"] = "Les jardins et la cour des Bien-nés",
		["Chillwind Camp: the {item:13704}"] = "Camp du Noroît : la {item:13704}",
		["Chillwind Camp: {npc:11023}"] = "Camp du Noroît : {npc:11023}",
		["Chillwind Camp: {npc:11056}"] = "Camp du Noroît : {npc:11056}",
		["Collected all through the city: Plagued Flesh Samples on the ghouls, the abominations and the crypt beasts (not on the skeletons); {item:13180} in the supply crates by the streets (some are trapped: plagued insects swarm out). Restless Souls: do not kill the Ghostly and Spectral Citizens; equip the blaster {npc:11140} gave you, target one and use the blaster on it, then again on the soul that breaks free."] = "À ramasser dans toute la ville : les échantillons de chair pestiférée (Plagued Flesh Sample) sur les goules, les abominations et les bêtes des cryptes (pas sur les squelettes) ; l'{item:13180} dans les caisses de ravitaillement le long des rues (certaines sont piégées : des insectes pestiférés en sortent). Âmes en peine : ne pas tuer les citoyens fantomatiques et spectraux (Ghostly Citizen, Spectral Citizen) ; équiper le fusil donné par {npc:11140}, en cibler un et utiliser le fusil sur lui, puis encore sur l'âme qui s'en libère.",
		["Collected all through the dungeon: the Dark Iron Fanny Packs, on the Anvilrage and Shadowforge dwarves (most of them carry one). The Relic Coffer Keys drop from the same dwarves, about one in eight, only for those on {quest:4123}: 12 keys open the 12 doors of the Black Vault (first visit), whoever carries them."] = "À ramasser dans tout le donjon : les sacoches Sombrefer (Dark Iron Fanny Packs), sur les nains Anvilrage et Shadowforge (la plupart en portent une). Les clés de coffre à reliques (Relic Coffer Keys) tombent des mêmes nains, environ une sur huit, seulement pour qui a {quest:4123} : 12 clés ouvrent les 12 portes de la chambre forte (Black Vault, première visite), quel que soit le joueur qui les porte.",
		["Dark Iron Highway: {npc:9016}"] = "Grand-route : {npc:9016}",
		["Detention Block: {npc:9021} and Windsor"] = "Prison : {npc:9021} et Windsor",
		["Detention Block: {quest:4264}"] = "Prison : {quest:4264}",
		["Detention Block: {quest:4322}"] = "Prison : {quest:4322}",
		["Dire Maul"] = "Hache-Tripes",
		["Dire Maul (dungeon, optional)"] = "Hache-Tripes (donjon, facultatif)",
		["Dire Maul West: before going in"] = "Hache-Tripes ouest : avant d'entrer",
		["Dire Maul stands on the plateau in the middle of {zone:1444}. The eastern wing opens on the east wall of the central courtyard, and from Eldreth Row at the city's gates; both lead to the upper level of the Warpwood Quarter."] = "Hache-Tripes se dresse sur le plateau au milieu de {zone:1444}. L'aile est s'ouvre sur le mur est de la cour centrale, et depuis l'allée d'Eldreth (Eldreth Row), aux portes de la cité ; les deux mènent au niveau supérieur de l'aile est (Warpwood Quarter).",
		["Dire Maul: before going in"] = "Hache-Tripes : avant d'entrer",
		["Dire Maul: quests not done"] = "Hache-Tripes : quêtes non finies",
		["Dire Maul: the eastern wing again"] = "Hache-Tripes : l'aile est, à nouveau",
		["Down into Tazz'Alaor, the trolls' hall: {npc:9236} (elite 59, two priests at her side), then down the great ramp and along the hall to {npc:9237} (elite 59, no adds, hits very hard)."] = "Descendre dans Tazz'Alaor, la salle des trolls : {npc:9236} (élite 59, deux prêtres à ses côtés), puis la grande rampe et la salle jusqu'à {npc:9237} (élite 59, sans renforts, frappe très fort).",
		["Dungeons 55-60 · Blackrock, Dire Maul, Stratholme, Scholomance"] = "Donjons 55-60 · Rochenoire, Hache-Tripes, Stratholme, Scholomance",
		["Each quest left: kept for another run, or abandoned"] = "Chaque quête restante : gardée pour une autre visite, ou abandonnée",
		["East along the hills to {npc:9459}'s cave."] = "Vers l'est par les collines jusqu'à la grotte de {npc:9459}.",
		["Escort {npc:9023}"] = "Escorter {npc:9023}",
		["Finished in the second or third visit only, or {npc:10813}'s head kept without the ride: hand them in now."] = "Finies seulement à la deuxième ou à la troisième visite, ou la tête de {npc:10813} gardée sans faire la route : les rendre maintenant.",
		["Fire Plume Ridge"] = "Crête de la Fournaise",
		["First visit, no key needed: the Detention Block (the prison), the Ring of the Law, the Shrine of Thaurissan, the Black Vault and the Hall of Crafting. Bosses 51 to 56: 54 or more advised."] = "Première visite, sans clé : la prison (Detention Block), l'arène (Ring of the Law), le sanctuaire de Thaurissan (Shrine of Thaurissan), la chambre forte (Black Vault) et la salle des artisans (Hall of Crafting). Boss 51 à 56 : niveau 54 ou plus conseillé.",
		["Flame Crest"] = "Corniche des flammes",
		["Flame Crest: {npc:10260} and {npc:9563}"] = "Corniche des flammes : {npc:10260} et {npc:9563}",
		["Flame Crest: {npc:10260}'s spider eggs"] = "Corniche des flammes : les œufs de {npc:10260}",
		["Flame Crest: {npc:10260}'s worg pup"] = "Corniche des flammes : le louveteau de {npc:10260}",
		["Flame Crest: {npc:9536}"] = "Corniche des flammes : {npc:9536}",
		["Flame Crest: {npc:9544}"] = "Corniche des flammes : {npc:9544}",
		["Flame Crest: {npc:9563}"] = "Corniche des flammes : {npc:9563}",
		["Fly to Lakeshire"] = "Vol pour Comté-du-Lac",
		["Fly to Morgan's Vigil"] = "Voler jusqu'à la Veille de Morgan",
		["Fly to Thorium Point"] = "Voler jusqu'à la Halte du Thorium",
		["Fly to {zone:1453}"] = "Prendre un vol pour {zone:1453}",
		["Fly to {zone:1455}"] = "Vol pour {zone:1455}",
		["For King Magni"] = "Pour le roi Magni",
		["For {npc:9560}"] = "Pour {npc:9560}",
		["From Cenarion Hold, the flight back to {zone:1450}."] = "Depuis le Fort cénarien, le vol de retour jusqu'à {zone:1450}.",
		["From Feathermoon, the flight to {zone:1450}. Now that you have been inside Dire Maul, {npc:11801} offers {quest:5527}, then {quest:5526}. A long chain: the Reliquary lies in Southwind Village, in {zone:1451}; back to {npc:11801} in {zone:1450}; then a new run of the eastern wing of Dire Maul, where the Felvine grows behind {npc:11492} (elite 58); and back to {npc:11801}. Take it only if your group means to run the eastern wing again. Alone? Skip it."] = "Depuis le bastion de Plumelune, le vol jusqu'à {zone:1450}. Après une visite de Hache-Tripes, {npc:11801} propose {quest:5527}, puis {quest:5526}. Une longue chaîne : le reliquaire se trouve au Village de Sudevent, en {zone:1451} ; retour chez {npc:11801} à {zone:1450} ; puis une nouvelle visite de l'aile est de Hache-Tripes, où la gangrevigne pousse derrière {npc:11492} (élite 58) ; et retour chez {npc:11801}. À prendre seulement si le groupe compte refaire l'aile est. Seul ? La passer.",
		["From the Shrine, the bridge leads into the Domicile, then to the upper balcony of the Hall of Crafting, which opens on the Black Vault: {npc:9041} and Verek (elite 56 and 55). With 12 Relic Coffer Keys, open the 12 {object:160836} doors; after the last one, the Warbringer Constructs wake, then {npc:9476} comes. The {object:161495} under the {object:160845} then holds the {object:165554}. Fewer than 12 keys? Leave it: the guide does not come back to the vault."] = "Depuis le sanctuaire, le pont mène aux logis (The Domicile), puis au balcon du haut de la salle des artisans (Hall of Crafting), qui donne sur la chambre forte (Black Vault) : {npc:9041} et Verek (élites 56 et 55). Avec 12 clés de coffre à reliques, ouvrir les 12 portes de {object:160836} ; après la dernière, les Warbringer Constructs se réveillent, puis {npc:9476} arrive. {object:161495}, sous {object:160845}, contient alors {object:165554}. Moins de 12 clés ? Laisser tomber : le guide ne revient pas à la chambre forte.",
		["From {zone:1450}, the flight to Cenarion Hold, then east to the ruins of Southwind Village. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Depuis {zone:1450}, le vol jusqu'au Fort cénarien, puis à l'est jusqu'aux ruines du Village de Sudevent. {object:179565} se trouve parmi les bâtiments en ruine, surveillé par des sentinelles torturées.",
		["Gadgetzan: {npc:5411}"] = "Gadgetzan : {npc:5411}",
		["Hall of Crafting: {npc:9056}"] = "Salle des artisans : {npc:9056}",
		["Hand the {item:12845} to {npc:10917}, then take {quest:5125}: he joins the fight against {npc:10440}."] = "Rendre le {item:12845} à {npc:10917}, puis prendre {quest:5125} : il rejoint le combat contre {npc:10440}.",
		["Hordemar City: {npc:10799}"] = "Cité de Hordemar : {npc:10799}",
		["Hordemar City: {npc:10799} and {npc:10257}"] = "Cité de Hordemar : {npc:10799} et {npc:10257}",
		["In the Bastion, {npc:11032} (elite 60) guards the Hoard: his strongbox, on the ground beside him, holds the {item:12845}. One medallion per run: whoever loots it keeps it for {npc:10917}, in the third visit. {npc:10997} (elite 60) holds the armoury and calls riflemen: the cannons of his room fire on them."] = "Dans le Bastion, {npc:11032} (élite 60) garde le Trésor (Hoard) : son coffre, par terre à côté de lui, contient le {item:12845}. Un seul médaillon par visite : qui le ramasse le garde pour {npc:10917}, à la troisième visite. {npc:10997} (élite 60) tient l'armurerie et appelle des fusiliers : les canons de sa salle tirent sur eux.",
		["In the Lyceum, the Shadowforge Flame Keepers (red armour) drop two Shadowforge Torches: light the two braziers at the back, the doors open on the Iron Hall. {npc:9938} (elite 57) waits at the far end: keep out of the fire jets of the side alcoves."] = "Dans le lycée (Lyceum), les Shadowforge Flame Keepers (armure rouge) donnent deux torches d'Ombreforge : allumer les deux braseros du fond, les portes s'ouvrent sur la salle de fer (Iron Hall). {npc:9938} (élite 57) attend au bout : rester hors des jets de feu des alcôves latérales.",
		["In the quest log: {quest:4022} ({npc:9459}), {quest:4263} ({npc:9561}). Keep one free quest log slot for {quest:4322}. For the third visit: {quest:4362} (Magni), {quest:4136}, {quest:4126}."] = "Dans le journal de quêtes : {quest:4022} ({npc:9459}), {quest:4263} ({npc:9561}). Garder une place libre dans le journal pour {quest:4322}. Pour la troisième visite : {quest:4362} (Magni), {quest:4136}, {quest:4126}.",
		["In the quest log: {quest:4341} (King Magni), {quest:4241} (Maxwell), {quest:4286} ({npc:9177}), {quest:4123} ({npc:9536}), {quest:3801} ({npc:8888}, if taken). For the next visits: {quest:4022} ({npc:9459}), {quest:4136} ({npc:9544}), {quest:4126} ({npc:1267}). Not on this route: {npc:9500}'s quest in the tavern (its herbs and silver are gathered outside), the {object:164869}'s (miners), {npc:14387}'s Attunement to the Core (raid)."] = "Dans le journal de quêtes : {quest:4341} (le roi Magni), {quest:4241} (Maxwell), {quest:4286} ({npc:9177}), {quest:4123} ({npc:9536}), {quest:3801} ({npc:8888}, si prise). Pour les visites suivantes : {quest:4022} ({npc:9459}), {quest:4136} ({npc:9544}), {quest:4126} ({npc:1267}). Pas sur ce parcours : la quête de {npc:9500} dans la taverne (ses herbes et son argent se récoltent dehors), celle de {object:164869} (mineurs), Attunement to the Core de {npc:14387} (raid).",
		["In the quest log: {quest:4701} ({npc:9562}), {quest:4729} and {quest:4862} ({npc:10260}), {quest:4866} ({npc:9563}). Given inside: {quest:4867} ({npc:10799}) and {quest:5001} ({npc:10257}). Not on this route: {item:12344} (Vaelan, inside: on Forever it no longer rewards the seal, and Upper Blackrock Spire, a 10-player dungeon, takes no key), The Final Tablets (the Mosh'aru tablets), Snakestone of the Shadow Huntress (Kilram, {zone:1452}), Deliana's dungeon set quests ({zone:1455})."] = "Dans le journal de quêtes : {quest:4701} ({npc:9562}), {quest:4729} et {quest:4862} ({npc:10260}), {quest:4866} ({npc:9563}). Données dedans : {quest:4867} ({npc:10799}) et {quest:5001} ({npc:10257}). Pas sur ce parcours : {item:12344} (Vaelan, dedans : sur Forever, la quête ne donne plus le sceau, et le pic Rochenoire supérieur, un donjon à 10 joueurs, ne demande aucune clé), The Final Tablets (les tablettes de Mosh'aru), Snakestone of the Shadow Huntress (Kilram, {zone:1452}), les quêtes d'ensembles de donjon de Deliana ({zone:1455}).",
		["In the quest log: {quest:5212} ({npc:11035}), {quest:5251} (Duke Nicholas), {quest:5214} ({npc:11033}), {quest:5243} (Leonid), {quest:5281} ({npc:11140}); Renfray's painting quest, for whoever took it. Not on this route: Sweet Serenity and Corruption ({zone:1452}), the dungeon set quests (Deliana, {npc:16016}), {npc:10508}'s chain ({object:176631})."] = "Dans le journal : {quest:5212} ({npc:11035}), {quest:5251} (duc Nicholas), {quest:5214} ({npc:11033}), {quest:5243} (Leonid), {quest:5281} ({npc:11140}) ; la quête du tableau de Renfray, pour qui l'a prise. Pas sur ce parcours : Sweet Serenity et Corruption ({zone:1452}), les quêtes d'ensembles de donjon (Deliana, {npc:16016}), la suite de {npc:10508} ({object:176631}).",
		["In the quest log: {quest:5213} ({npc:11035}), {quest:5263} (Duke Nicholas). Whoever carries the {item:12845}: {npc:10917}, just inside."] = "Dans le journal de quêtes : {quest:5213} ({npc:11035}), {quest:5263} (le duc Nicholas). Qui porte le {item:12845} : {npc:10917}, juste après l'entrée.",
		["In the quest log: {quest:5343} ({npc:11023}), {quest:5382} ({npc:11216}), {quest:5529} ({npc:11035}). Share the three with your group: click each in the quest log, then Share. Not on this route: {item:12368}, the dungeon set quests, the class quests."] = "Dans le journal de quêtes : {quest:5343} ({npc:11023}), {quest:5382} ({npc:11216}), {quest:5529} ({npc:11035}). Partager les trois avec le groupe : cliquer sur chacune dans le journal de quêtes, puis sur Partager. Pas sur ce parcours : {item:12368}, les quêtes d'ensembles de donjon, les quêtes de classe.",
		["In the quest log: {quest:7488} ({npc:7877}), {quest:7482} (Runethorn), {quest:7441}. A class book found in the dungeon starts a quest of its own: it goes to {npc:14368}, in the Athenaeum (western wing). Not on this route: the northern wing's quests, Lydros's libram quests."] = "Dans le journal de quêtes : {quest:7488} ({npc:7877}), {quest:7482} (Runethorn), {quest:7441}. Un livre de classe trouvé dans le donjon lance une quête à part : il va à {npc:14368}, dans l'Athénée (Athenaeum, aile ouest). Pas sur ce parcours : les quêtes de l'aile nord, les quêtes de libram de Lydros.",
		["Into Blackrock Mountain on the {zone:1428} side. Two ways to the portal: the door beside the Blackrock Spire meeting stone and the path up (elites on it), or along the great chain and the wall to the balcony where Bodley stands, then a jump down onto it, with no fight. Inside, the stairs up on the left lead to Upper Blackrock Spire: not this time."] = "Entrer dans le Mont Rochenoire du côté de {zone:1428}. Deux chemins jusqu'au portail : la porte à côté de la pierre de rencontre du pic Rochenoire et le chemin qui monte (des élites dessus), ou le long de la grande chaîne et du mur jusqu'au balcon où se tient Bodley, puis un saut dessus, sans combat. Dedans, l'escalier qui monte à gauche mène au pic Rochenoire supérieur : pas cette fois.",
		["Keep 12 free quest log slots. Most of these quests cannot be shared: each player takes their own."] = "Garder 12 places libres dans le journal de quêtes. La plupart de ces quêtes ne se partagent pas : chaque joueur prend la sienne.",
		["Keep 2 free quest log slots."] = "Garder 2 places libres dans le journal de quêtes.",
		["Keep 4 free quest log slots."] = "Garder 4 places libres dans le journal de quêtes.",
		["Keep 8 free quest log slots. Scholomance is asked next, here too: one of its quests is given in this chapel."] = "Garder 8 places libres dans le journal de quêtes. La Scholomance est demandée juste après, ici aussi : une de ses quêtes se prend dans cette chapelle.",
		["Keep 8 free quest log slots. The northern wing (the ogres' tribute) is not in the guide."] = "Garder 8 places libres dans le journal de quêtes. L'aile nord (le tribut des ogres) n'est pas dans le guide.",
		["Keep 9 free quest log slots."] = "Garder 9 places libres dans le journal de quêtes.",
		["Kept for another run, or abandoned"] = "Gardée pour une autre visite, ou abandonnée",
		["Kharanos: {npc:1267}"] = "Kharanos : {npc:1267}",
		["Lakeshire flight master"] = "Maître de vol de Comté-du-Lac",
		["Lakeshire: {npc:344}"] = "Comté-du-Lac : {npc:344}",
		["Lariss Pavilion: {npc:14355}"] = "Pavillon de Lariss : {npc:14355}",
		["Leave the dungeon without resetting it: as long as the group stays together, the same instance waits, bosses alive (to check in game). Ride to Morgan's Vigil and back, a good quarter of an hour; a hearthstone bound at the Vigil shortens the way there."] = "Sortir du donjon sans le réinitialiser : tant que le groupe reste ensemble, la même instance attend, boss en vie (à vérifier en jeu). Aller jusqu'à la Veille de Morgan et revenir, un bon quart d'heure ; une pierre de foyer liée à la Veille raccourcit l'aller.",
		["Light's Hope Chapel"] = "Chapelle de l'Espoir de Lumière",
		["Light's Hope Chapel: Scholomance"] = "Chapelle de l'Espoir de Lumière : Scholomance",
		["Light's Hope Chapel: Stratholme"] = "Chapelle de l'Espoir de Lumière : Stratholme",
		["Light's Hope Chapel: what is left to hand in"] = "Chapelle de l'Espoir de Lumière : ce qui reste à rendre",
		["Light's Hope Chapel: {npc:11033}"] = "Chapelle de l'Espoir de Lumière : {npc:11033}",
		["Light's Hope Chapel: {npc:11035}"] = "Chapelle de l'Espoir de Lumière : {npc:11035}",
		["Light's Hope Chapel: {npc:11036}"] = "Chapelle de l'Espoir de Lumière : {npc:11036}",
		["Light's Hope Chapel: {npc:11039}"] = "Chapelle de l'Espoir de Lumière : {npc:11039}",
		["Light's Hope Chapel: {quest:5262}"] = "Chapelle de l'Espoir de Lumière : {quest:5262}",
		["Lower Blackrock Spire (dungeon, optional)"] = "Pic Rochenoire inférieur (donjon, facultatif)",
		["Lower Blackrock Spire: along the way"] = "Pic Rochenoire inférieur : en chemin",
		["Lower Blackrock Spire: before going in"] = "Pic Rochenoire inférieur : avant d'entrer",
		["Lower Blackrock Spire: quests not done"] = "Pic Rochenoire inférieur : quêtes non finies",
		["Lower Blackrock Spire: the orc city in the upper part of Blackrock Mountain, above Blackrock Depths. Levels 55 to 60, bosses 58 to 60: a group of 5 at 58 to 60 (possible from about 56, difficult). The quests come from Morgan's Vigil and Flame Crest, one more from a goblin hidden inside; the run has one short trip out to Morgan's Vigil and back. Alone? Skip it."] = "Pic Rochenoire inférieur : la cité des orcs dans le haut du Mont Rochenoire, au-dessus des Profondeurs de Rochenoire. Niveaux 55 à 60, boss 58 à 60 : un groupe de 5 aux niveaux 58 à 60 (possible vers 56, difficile). Les quêtes se prennent à la Veille de Morgan et à la Corniche des flammes, une de plus auprès d'une gobeline cachée dedans ; le passage compte un court aller-retour jusqu'à la Veille de Morgan. Seul ? Le passer.",
		["Maxwell sends you to {npc:9563}, at Flame Crest: the guide goes there next."] = "Maxwell envoie voir {npc:9563}, à la Corniche des flammes : le guide y va ensuite.",
		["Maxwell's next quest, {npc:10363}'s Demise, is for Upper Blackrock Spire (10 players): not in this guide."] = "La quête suivante de Maxwell, qui envoie tuer {npc:10363}, est pour le pic Rochenoire supérieur (10 joueurs) : pas dans ce guide.",
		["Morgan's Vigil"] = "Veille de Morgan",
		["Morgan's Vigil flight master"] = "Maître de vol de la Veille de Morgan",
		["Morgan's Vigil: {npc:9177}"] = "Veille de Morgan : {npc:9177}",
		["Morgan's Vigil: {npc:9560}"] = "Veille de Morgan : {npc:9560}",
		["Morgan's Vigil: {npc:9561}"] = "Veille de Morgan : {npc:9561}",
		["Morgan's Vigil: {npc:9562}"] = "Veille de Morgan : {npc:9562}",
		["Morgan's Vigil: {quest:4182}"] = "Veille de Morgan : {quest:4182}",
		["Morgan's Vigil: {quest:5089}"] = "Veille de Morgan : {quest:5089}",
		["Nighthaven"] = "Havrenuit",
		["Out by the {object:175461} in {object:175440} (or the way you came) and back to Light's Hope Chapel. Duke Nicholas takes the head and sends you after {npc:10440}, the last boss of the dead side: the third visit, in the same instance. Rather not ride again? Skip this step: {quest:5263} then waits for another run."] = "Sortir par {object:175461} sur {object:175440} (ou par où le groupe est venu) et revenir à la chapelle de l'Espoir de Lumière. Le duc Nicholas prend la tête et envoie tuer {npc:10440}, le dernier boss du côté mort-vivant : la troisième visite, dans la même instance. Pas envie de refaire la route ? Passer cette étape : {quest:5263} attend alors une autre visite.",
		["Out of Blackrock Mountain on the {zone:1428} side, then north-east to Flame Crest."] = "Sortir du Mont Rochenoire du côté de {zone:1428}, puis aller au nord-est jusqu'à la Corniche des flammes.",
		["Out of Stratholme, back east to Light's Hope Chapel."] = "Sortir de Stratholme et revenir vers l'est jusqu'à la chapelle de l'Espoir de Lumière.",
		["Out of the Bastion, {object:175433}: {npc:10516} (elite 57) calls spirits, kill them first. Then {object:175440}: {npc:10435} (elite 58) stands before Alonsus Chapel and drops the {item:12382}. It opens the {object:175461}, the gate on this square, and the gate of the Gauntlet: one key in the group is enough, whoever loots it keeps it for the third visit. Leave the dungeon by the {object:175461}, or the way you came; keep the group together, without resetting the instance: the next two visits come back into it. An instance left empty too long may reset itself (to check in game): do not linger between visits."] = "En sortant du Bastion, {object:175433} : {npc:10516} (élite 57) appelle des esprits, les tuer d'abord. Puis {object:175440} : {npc:10435} (élite 58) se tient devant la chapelle d'Alonsus (Alonsus Chapel) et donne la {item:12382}. Elle ouvre {object:175461}, la porte de cette place, et la porte du Défilé (Gauntlet) : une clé dans le groupe suffit, qui la ramasse la garde pour la troisième visite. Sortir du donjon par {object:175461}, ou par où le groupe est venu ; rester groupés, sans réinitialiser l'instance : les deux visites suivantes y reviennent. Une instance restée vide trop longtemps peut se réinitialiser (à vérifier en jeu) : ne pas traîner entre deux visites.",
		["Out of the Spire, north-east to Flame Crest. {npc:9563}: his talk option, while the poison is still on you. Poison gone? {quest:4866} cannot be done this time: skip this step."] = "Sortir du Pic, puis aller au nord-est jusqu'à la Corniche des flammes. {npc:9563} : son option de dialogue, tant que le poison est encore là. Le poison est parti ? {quest:4866} ne peut pas se faire cette fois : passer cette étape.",
		["Out of the dungeon (the way back or your hearthstone), then out of Blackrock Mountain on the {zone:1428} side, north-east to Flame Crest."] = "Sortir du donjon (à pied ou avec la pierre de foyer), puis du Mont Rochenoire du côté de {zone:1428}, et aller au nord-est jusqu'à la Corniche des flammes.",
		["Out to Eva again. {quest:5384}: she hands over the {item:13523} (Warcraft Tavern also has the {npc:14861} drop it: to check in game)."] = "Ressortir voir Eva. {quest:5384} : elle donne le {item:13523} (d'après Warcraft Tavern, le {npc:14861} le donne aussi : à vérifier en jeu).",
		["Past the entrance door, Hordemar City. {npc:10799} walks around its first part. {npc:10257} waits on a ledge overlooking the city: one of the ramps down to Tazz'Alaor, the trolls' hall with the purple light, climbs to her. Her belongings are in a small chest tucked in a corner at the bottom of Hordemar City (it has several places). Leave {npc:9196}, {npc:9237} and {npc:9568} alive for now: {npc:9560}'s quest, given for {npc:10257}'s message, asks for them."] = "Passé la porte d'entrée, la cité de Hordemar (Hordemar City). {npc:10799} se promène dans sa première partie. {npc:10257} attend sur une corniche qui domine la cité : l'une des rampes qui descendent vers Tazz'Alaor, la salle des trolls à la lumière violette, monte jusqu'à elle. Ses affaires sont dans un petit coffre, dans un coin au fond de la cité de Hordemar (il a plusieurs emplacements). Laisser {npc:9196}, {npc:9237} et {npc:9568} en vie pour l'instant : la quête de {npc:9560}, donnée pour le message de {npc:10257}, les demande.",
		["Past {npc:9736}, {npc:10220}'s lair: the great worg (elite 59) and her pups. {npc:10268} runs in right after her death: no time to rest in between."] = "Après {npc:9736}, l'antre de {npc:10220} : la grande worg (élite 59) et ses petits. {npc:10268} arrive aussitôt après sa mort : pas de repos entre les deux.",
		["Ride back east to Light's Hope Chapel, a good ten minutes. {npc:11035}'s next quest is for the third visit."] = "Revenir vers l'est jusqu'à la chapelle de l'Espoir de Lumière, une bonne dizaine de minutes. La quête suivante de {npc:11035} est pour la troisième visite.",
		["Ride back south to Morgan's Vigil. Maxwell's next quest, Stormwind Rendezvous, starts the long chain to Onyxia's Lair, through Upper Blackrock Spire: not in this guide."] = "Revenir au sud jusqu'à la Veille de Morgan. La quête suivante de Maxwell, Stormwind Rendezvous, ouvre la longue chaîne du repaire d'Onyxia, par le pic Rochenoire supérieur : pas dans ce guide.",
		["Ride back south to the Vigil: Maxwell now sends you after {quest:4241}, in the dungeon's prison."] = "Revenir au sud jusqu'à la Veille : Maxwell envoie maintenant chercher {quest:4241}, dans la prison du donjon.",
		["Ride back to Morgan's Vigil. {quest:4242}: Maxwell takes the bad news; pick your reward. From now on, the Anvilrage dwarves of the Detention Block drop {quest:4264} for you (second visit)."] = "Revenir à la Veille de Morgan. {quest:4242} : Maxwell reçoit la mauvaise nouvelle ; choisir sa récompense. Désormais, les nains Anvilrage de la prison peuvent donner {quest:4264} (deuxième visite).",
		["Ride back west to Chillwind Camp. {npc:11023}'s next quest, The Last Barov, is in Horde lands: not in this guide."] = "Revenir vers l'ouest jusqu'au Camp du Noroît. La quête suivante de {npc:11023}, The Last Barov, est en terres de la Horde : pas dans ce guide.",
		["Ride east to the lake and onto Caer Darrow. {npc:11216}, a ghost, stands with Lucien before the door of Scholomance."] = "Partir vers l'est jusqu'au lac et à Caer Darrow. {npc:11216}, un fantôme, se tient avec Lucien devant la porte de la Scholomance.",
		["Ride north along the road, then climb to the goblin camp on Flame Crest. {npc:9563} tells his story in the camp; {npc:9536} and {npc:9544} give one quest each for the dungeon."] = "Suivre la route vers le nord, puis monter jusqu'au camp gobelin de la Corniche des flammes. {npc:9563} raconte son histoire dans le camp ; {npc:9536} et {npc:9544} donnent chacun une quête pour le donjon.",
		["Ride north to Flame Crest. {npc:10260} stands inside the cave: his two quests give two pets, the {item:12264} and the {item:12529}, and he hands over an {item:12262}. {npc:9563}, in the camp: {quest:4866}, a rare reward."] = "Monter au nord jusqu'à la Corniche des flammes. {npc:10260} se tient dans la grotte : ses deux quêtes donnent deux mascottes, le {item:12264} et le {item:12529}, et il remet une {item:12262}. {npc:9563}, dans le camp : {quest:4866}, une récompense rare.",
		["Ride north-east from the Vigil into the hills: Broodlings, Dragonspawn and Wyrmkin in packs, the three Black Drakes apart, one in the northern hills and two further south."] = "Partir au nord-est de la Veille, dans les collines : Broodlings, Dragonspawn et Wyrmkin en groupes, les trois Black Drakes à part, l'un dans les collines du nord, les deux autres plus au sud.",
		["Ride out of {zone:1455} down to Kharanos: {npc:1267} is in the Thunderbrew Distillery. His lost recipe is in the Grim Guzzler, the tavern of Blackrock Depths (third visit)."] = "Sortir de {zone:1455} et descendre jusqu'à Kharanos : {npc:1267} est dans la distillerie Tonnebière (Thunderbrew Distillery). Sa recette perdue est dans la taverne des Profondeurs de Rochenoire (Grim Guzzler, troisième visite).",
		["Ride south through the {zone:1422} to the lake and onto Caer Darrow: Renfray paints inside the ruined house. His quest cannot be shared. Then back north-east to Stratholme."] = "Descendre au sud à travers les {zone:1422} jusqu'au lac et à Caer Darrow : Renfray peint dans la maison en ruine. Sa quête ne se partage pas. Puis remonter au nord-est vers Stratholme.",
		["Ride west across the zone to Terrordale: {npc:11140} waits in the westernmost of its three houses, where the route found him. His blaster frees the ghosts of Stratholme."] = "Traverser la zone vers l'ouest jusqu'à Val-Terreur : {npc:11140} attend dans la plus à l'ouest de ses trois maisons, là où le parcours l'a trouvé. Son fusil libère les fantômes de Stratholme.",
		["Ride west across the zone to {npc:11140}'s house in Terrordale."] = "Traverser la zone vers l'ouest jusqu'à la maison de {npc:11140}, à Val-Terreur.",
		["Ride west along the road, past Blackrock Stronghold, into Blackrock Mountain. Inside, cross the great chain to the hanging building in the middle (Forgewright's Tomb), go down through it, then down the next chain to the Grinding Quarry: {quest:4262} (elite 52) walks there. The dungeon's door is past the quarry, on the left, at the far end of the Masonry."] = "Suivre la route vers l'ouest, passer le bastion de Rochenoire et entrer dans le Mont Rochenoire. Dedans, traverser la grande chaîne jusqu'au bâtiment suspendu du milieu (Forgewright's Tomb), descendre à travers, puis descendre la chaîne suivante jusqu'à la carrière (Grinding Quarry) : {quest:4262} (élite 52) y circule. La porte du donjon est après la carrière, sur la gauche, au fond de la maçonnerie (Masonry).",
		["Ring of the Law and the Shrine of Thaurissan"] = "L'arène et le sanctuaire de Thaurissan",
		["Ruins of Thaurissan: the relics"] = "Ruines de Thaurissan : les reliques",
		["Scholomance"] = "Scholomance",
		["Scholomance (dungeon, optional)"] = "Scholomance (donjon, facultatif)",
		["Scholomance: before going in"] = "Scholomance : avant d'entrer",
		["Scholomance: quests not done"] = "Scholomance : quêtes non finies",
		["Scholomance: the school of necromancy under Caer Darrow, the island of the lake in the south-east of the {zone:1422}. Levels 58 to 60, bosses 58 to 62: a group of 5 at 59 or 60. Its door opens only with the {item:13704}, the reward of {quest:5505}, a long chain from {npc:11056} at Chillwind Camp that the guide offers before the run: one key in the group is enough. The guide runs it after Stratholme; {npc:11035}, in this chapel, gives one of its quests, the others come from Chillwind Camp and from {npc:11216} at its door. Alone? Skip it."] = "Scholomance : l'école de nécromancie sous Caer Darrow, l'île du lac au sud-est des {zone:1422}. Niveaux 58 à 60, boss de 58 à 62 : un groupe de 5 de niveau 59 ou 60. Sa porte ne s'ouvre qu'avec la {item:13704}, récompense de {quest:5505}, une longue suite d'{npc:11056} au camp du Noroît que le guide propose avant le donjon : une clé dans le groupe suffit. Le guide la fait après Stratholme ; {npc:11035}, dans cette chapelle, donne une de ses quêtes, les autres viennent du camp du Noroît et de {npc:11216} devant sa porte. Seul ? La passer.",
		["Scholomance: {npc:10503}"] = "Scholomance : {npc:10503}",
		["Scholomance: {quest:5384}"] = "Scholomance : {quest:5384}",
		["Second visit: back into the same instance by the main gate, through the cleared streets to the Scarlet Bastion's last chamber. {npc:10812} (elite 62) turns into {npc:10813}, a dread lord, during the fight: dispel his Deep Sleep, stand at range from his Psychic Scream. His head starts {quest:5262} for those who handed in {quest:5251}: right-click it."] = "Deuxième visite : retour dans la même instance par la grande porte, à travers les rues déjà nettoyées, jusqu'à la dernière salle du Bastion écarlate. {npc:10812} (élite 62) se change en {npc:10813}, un seigneur de l'effroi, pendant le combat : dissiper son Sommeil profond, se tenir à distance de son Cri psychique. Sa tête lance {quest:5262} pour ceux qui ont rendu {quest:5251} : clic droit dessus.",
		["Shadowforge City: {npc:9017}"] = "Ville d'Ombreforge : {npc:9017}",
		["Share {quest:4286}, {quest:4123} and {quest:4126} with your group: click each in the quest log, then Share. The others cannot be shared."] = "Partager {quest:4286}, {quest:4123} et {quest:4126} avec le groupe : cliquer sur chacune dans le journal de quêtes, puis sur Partager. Les autres ne se partagent pas.",
		["Share {quest:5212}, {quest:5251}, {quest:5214} and {quest:5243} with your group: click each in the quest log, then Share. {quest:5281} and Renfray's painting quest cannot be shared."] = "Partager {quest:5212}, {quest:5251}, {quest:5214} et {quest:5243} avec le groupe : clic sur chacune dans le journal, puis Partager. {quest:5281} et la quête du tableau de Renfray ne se partagent pas.",
		["Shrine of Thaurissan: the monument"] = "Sanctuaire de Thaurissan : le monument",
		["Skeletal remains, beside {npc:14368}"] = "Restes du squelette, à côté de {npc:14368}",
		["Skitterweb Tunnels: {npc:10596}"] = "Tunnels des araignées : {npc:10596}",
		["Solomon is in the town hall of Lakeshire."] = "Solomon est dans l'hôtel de ville de Comté-du-Lac.",
		["Southwind Village"] = "Village de Sudevent",
		["Stratholme"] = "Stratholme",
		["Stratholme (dungeon, optional)"] = "Stratholme (donjon, facultatif)",
		["Stratholme, first visit: before going in"] = "Stratholme, première visite : avant d'entrer",
		["Stratholme, second visit: {npc:10813}"] = "Stratholme, deuxième visite : {npc:10813}",
		["Stratholme, third visit: before going in"] = "Stratholme, troisième visite : avant d'entrer",
		["Stratholme: along the way"] = "Stratholme : en chemin",
		["Stratholme: quests not done"] = "Stratholme : quêtes non finies",
		["Stratholme: the dead city in the north-west of the {zone:1423}, levels 58 to 60, bosses 57 to 62: a group of 5 at 58 to 60; possible from about 56, difficult. The quests come from Light's Hope Chapel, from {npc:11140} in Terrordale and, for whoever helped {npc:1855} on the route ({quest:5845}), from {npc:11936} on Caer Darrow. Its quest chains ask for three visits to the same instance: the living side, then {npc:10813}, then the dead side, with rides back to Light's Hope in between. Alone? Skip it."] = "Stratholme : la ville morte au nord-ouest des {zone:1423}, niveaux 58 à 60, boss de 57 à 62 : un groupe de 5 de niveau 58 à 60 ; possible dès 56 environ, difficile. Les quêtes viennent de la chapelle de l'Espoir de Lumière, de {npc:11140} à Val-Terreur et, pour qui a aidé {npc:1855} sur le parcours ({quest:5845}), de {npc:11936} à Caer Darrow. Ses suites de quêtes demandent trois passages dans la même instance : le côté vivant, puis {npc:10813}, puis le côté mort, avec des retours à l'Espoir de Lumière entre les deux. Seul ? La passer.",
		["Tazz'Alaor: {npc:9237}"] = "Tazz'Alaor : {npc:9237}",
		["Terrordale: {npc:11140}"] = "Val-Terreur : {npc:11140}",
		["The Anvilrage dwarves of the Detention Block drop {quest:4264} (about one in four) to those who handed in {quest:4242}: right-click it. Kill Gerstahn again for the {item:11140} and bring the note to Windsor."] = "Les nains Anvilrage de la prison donnent {quest:4264} (environ une fois sur quatre) à qui a rendu {quest:4242} : clic droit dessus. Tuer de nouveau Gerstahn pour la {item:11140} et apporter le billet à Windsor.",
		["The Athenaeum: {quest:7482}"] = "L'Athénée : {quest:7482}",
		["The Barov Family Vault: the six chambers"] = "Le caveau des Barov : les six salles",
		["The Bloodaxe Worg Pups play in Hordemar City and in {npc:10220}'s lair: target one and use the {item:12262}. The Spire Spider Eggs lie in the Skitterweb Tunnels, {npc:10596}'s halls: each egg sac gives 1 to 3, and spiderlings may hatch from them."] = "Les louveteaux worgs Bloodaxe (Bloodaxe Worg Pups) jouent dans la cité de Hordemar et dans l'antre de {npc:10220} : en cibler un et utiliser la {item:12262}. Les œufs d'araignée du Pic (Spire Spider Eggs) sont dans les tunnels des araignées (Skitterweb Tunnels), le domaine de {npc:10596} : chaque cocon en donne 1 à 3, et des araignées peuvent en éclore.",
		["The Detention Block opens past the entrance. {npc:9018}, in the southernmost room, drops the {item:11140}, which opens the cells (a rogue can pick them instead). {quest:4341} and {quest:4241} are locked in the cells of the south-east corridor: listen to {npc:9021}'s whole story; Windsor has given up, and his news goes back to Maxwell. {npc:9025} patrols the northern ring, {npc:9319} waits at its lowest point. To check in game: which cell holds whom."] = "La prison (Detention Block) s'ouvre après l'entrée. {npc:9018}, dans la salle la plus au sud, donne la {item:11140}, qui ouvre les cellules (un voleur peut les crocheter). {quest:4341} et {quest:4241} sont enfermés dans les cellules du couloir sud-est : écouter toute l'histoire de {npc:9021} ; Windsor a perdu espoir, et ses nouvelles repartent chez Maxwell. {npc:9025} patrouille dans l'anneau nord, {npc:9319} attend à son point le plus bas. À vérifier en jeu : quelle cellule pour qui.",
		["The Domicile and the Black Vault"] = "Les logis et la chambre forte",
		["The Imperial Seat: {npc:9019}"] = "Le siège impérial : {npc:9019}",
		["The Reliquary and the Chamber of Summoning"] = "Le Reliquaire et la Chambre d'invocation",
		["The Reliquary, the first great hall: the {object:176486} lies on a table in its back left corner, seen from the entrance. Then the Chamber of Summoning, and the great room after it: the {object:176487} lies on a table in its far corner, opposite the way in. Each player clicks the deeds for their own quest (to check in game)."] = "Le Reliquaire (Reliquary), la première grande salle : {object:176486} est posé sur une table dans son coin du fond à gauche, vu de l'entrée. Puis la Chambre d'invocation (Chamber of Summoning) et la grande salle qui la suit : {object:176487} est posé sur une table dans son coin opposé à l'entrée. Chaque joueur clique sur les titres pour sa propre quête (à vérifier en jeu).",
		["The Scarlet Bastion: the painting"] = "Le Bastion écarlate : le tableau",
		["The Scarlet Bastion: {npc:10811}"] = "Le Bastion écarlate : {npc:10811}",
		["The Scarlet Bastion: {object:176112}"] = "Le Bastion écarlate : {object:176112}",
		["The Slaughterhouse: {npc:10440}"] = "L'Abattoir : {npc:10440}",
		["The Slaughterhouse: {npc:10917}, after the fight"] = "L'Abattoir : {npc:10917}, après le combat",
		["The Viewing Room and the Laboratory"] = "La Salle d'observation et le Laboratoire",
		["The Viewing Room: Vectus and {npc:10433} stand among neutral students and fight only for {item:12368}: leave them. Then the Laboratory: {npc:10508} (elite 62), a lich who fears and knocks back. {item:13471} lies by the west wall of the Laboratory, at the back, past the alchemy lab."] = "La Salle d'observation (Viewing Room) : Vectus et {npc:10433} se tiennent parmi des élèves neutres et ne se battent que pour {item:12368} : les laisser. Puis le Laboratoire (Laboratory) : {npc:10508} (élite 62), une liche qui effraie et repousse. {item:13471} est près du mur ouest du Laboratoire, au fond, après le laboratoire d'alchimie.",
		["The black dragonkin"] = "Les draconiens noirs",
		["The door at the back of {npc:11492}'s room opens with the {item:18249} straight onto the Lariss Pavilion."] = "La porte au fond de la salle de {npc:11492} s'ouvre avec la {item:18249} directement sur le pavillon de Lariss.",
		["The first pylon stands in the Capital Gardens, right in front of the entrance. Kill the wandering Ancients before {npc:11489} (elite 60), who calls them all. Upstairs, the Court of the Highborne: two more pylons, {npc:11488} and {npc:11487}. The {npc:14358} stands on the bridge of the upper level."] = "Le premier pylône se dresse dans les jardins de la capitale (Capital Gardens), juste devant l'entrée. Tuer les Anciens qui errent avant {npc:11489} (élite 60), qui les appelle tous. À l'étage, la cour des Bien-nés (Court of the Highborne) : deux autres pylônes, {npc:11488} et {npc:11487}. {npc:14358} se tient sur le pont du niveau supérieur.",
		["The key: one player of the group has it, or takes {quest:3801} here"] = "La clé : un joueur du groupe l'a déjà, ou prend {quest:3801} ici",
		["The last boss, {npc:9568} (elite 60), calls two adds at half health. He drops {quest:5089} for each player: right-click it."] = "Le dernier boss, {npc:9568} (élite 60), appelle deux renforts à la moitié de sa vie. Il donne {quest:5089} à chaque joueur : clic droit dessus.",
		["The last hall: six chambers round the Barov Family Vault. Below, from the left: {npc:10502}, {npc:10504} (the {object:176485} lies on a slab beside him), {npc:10507}. Above, from the left: {npc:10901}, {npc:11261} (he enrages at half health: burn him fast), {npc:10505}. In Krastinov's chamber, burn the {object:176544} and of {npc:11217}, one on each side. {npc:1853} comes into the vault once the six are dead; he sends players into the side chambers."] = "La dernière salle : six chambres autour du caveau de la famille Barov (Barov Family Vault). En bas, depuis la gauche : {npc:10502}, {npc:10504} ({object:176485} est posé sur une dalle à côté de lui), {npc:10507}. En haut, depuis la gauche : {npc:10901}, {npc:11261} (il s'enrage à la moitié de sa vie : le tuer vite), {npc:10505}. Dans la salle de Krastinov, brûler {object:176544} et les restes de {npc:11217}, un de chaque côté. {npc:1853} entre dans le caveau une fois les six morts ; il envoie des joueurs dans les salles du tour.",
		["The last two pylons stand either side of the door of the Prison of Immol'thar: with all five down, its force field is gone. {npc:11496} (elite 61) calls adds and moves players to the middle of the room; he enrages at half health. A small tunnel then leads to the Athenaeum: {npc:11486} (elite 60)."] = "Les deux derniers pylônes se dressent de chaque côté de la porte de la prison d'Immol'thar : une fois les cinq éteints, son champ de force disparaît. {npc:11496} (élite 61) appelle des renforts et déplace des joueurs au milieu de la salle ; il s'enrage à la moitié de sa vie. Un petit tunnel mène ensuite à l'Athénée (Athenaeum) : {npc:11486} (élite 60).",
		["The open gate on the east side of the Detention Block leads into the Ring of the Law: the gate closes behind you, two waves of beasts come, then a random boss. Once it is down, a second gate opens into the East Garrison. From there, climb the stairs beside the arena gate and walk round the stands, close to the inner railing (the Arena Spectators come at you when you pass too near), to the Shrine of Thaurissan: {npc:9024} kneels before the {object:164689}."] = "La grille ouverte du côté est de la prison mène dans l'arène (Ring of the Law) : la grille se ferme derrière le groupe, deux vagues de bêtes arrivent, puis un boss au hasard. Une fois celui-ci tombé, une deuxième grille s'ouvre sur la garnison est (East Garrison). De là, monter l'escalier à côté de la grille de l'arène et faire le tour des gradins, au ras de la rambarde intérieure (les spectateurs, Arena Spectators, attaquent quand on passe trop près), jusqu'au sanctuaire de Thaurissan (Shrine of Thaurissan) : {npc:9024} est agenouillé devant {object:164689}.",
		["The relics are the carved stones scattered through the Ruins of Thaurissan, west of Flame Crest: click them until the information is recovered. The War Reavers and Thaurissan Firewalkers there are 53-55, and {npc:8978} (57) holds the {object:147516} camp south-west of Flame Crest: take the relics at the edge of the ruins."] = "Les reliques sont les pierres sculptées éparpillées dans les ruines de Thaurissan, à l'ouest de la Corniche des flammes : les cliquer jusqu'à récupérer l'information. Les Ravageurs de guerre et les Marchefeux de Thaurissan y sont de niveau 53-55, et {npc:8978} (57) tient le camp {object:147516} au sud-ouest de la Corniche des flammes : prendre les reliques au bord des ruines.",
		["The rewards include the {item:13544}: worn, it shows {npc:11286}, beside Eva. His chain against {npc:10508} goes to Stromgarde in the {zone:1417}, then Light's Hope Chapel, Stratholme ({object:176631}, before the Baron) and back to Scholomance: not in this guide."] = "Les récompenses comprennent l'{item:13544} : portée, elle fait voir {npc:11286}, à côté d'Eva. Sa chaîne contre {npc:10508} passe par Stromgarde dans les {zone:1417}, puis la chapelle de l'Espoir de Lumière, Stratholme ({object:176631}, devant le baron) et revient à la Scholomance : pas dans ce guide.",
		["The second and third visits need the {item:11000}: one in the group is enough ({quest:3801}, first visit). Nobody has it? Skip {quest:4282}: the guide leaves these two visits out. Second visit, with the key: Windsor's note, the Dark Iron Highway ({npc:9016}), Shadowforge City (Incendius), the West Garrison (Angerforge), the Manufactory (Argelmach), then {quest:4322} from Windsor's cell. Bosses 52 to 57: 56 or more advised. From Thorium Point, ride south across the {zone:1427} into Blackrock Mountain."] = "Les deuxième et troisième visites demandent la {item:11000} : une dans le groupe suffit ({quest:3801}, première visite). Personne ne l'a ? Passer {quest:4282} : le guide laisse alors ces deux visites de côté. Deuxième visite, avec la clé : le billet pour Windsor, la grand-route (Dark Iron Highway, {npc:9016}), la ville d'Ombreforge (Shadowforge City, Incendius), la garnison ouest (West Garrison, Angerforge), la manufacture (Manufactory, Argelmach), puis {quest:4322} depuis la cellule de Windsor. Boss 52 à 57 : niveau 56 ou plus conseillé. Depuis la Halte du Thorium, traverser {zone:1427} vers le sud jusqu'au Mont Rochenoire.",
		["The skeletal remains lie on the floor beside {npc:14368}, in the Athenaeum: choose to mourn the great loss."] = "Les restes du squelette gisent par terre à côté de {npc:14368}, dans l'Athénée : choisir de pleurer cette grande perte.",
		["The spiders' tunnels: the eggs for {npc:10260}. {npc:10596} (elite 59) waits at the top. Whoever has {quest:4866} lets her poison them, and nobody removes that poison; then kill her. The poison must still be there at {npc:9563}'s: if it would wear off before the end of the run (to check in game), that player goes out right after her and comes back."] = "Les tunnels des araignées : les œufs pour {npc:10260}. {npc:10596} (élite 59) attend au sommet. Celui qui a {quest:4866} se laisse empoisonner par elle, et personne ne retire ce poison ; puis la tuer. Le poison doit être encore là chez {npc:9563} : s'il risque de s'arrêter avant la fin du donjon (à vérifier en jeu), ce joueur sort juste après elle et revient.",
		["The {item:11000} opens the doors of the second and third visits (the Shadowforge Gates of the prison and the {object:161460}): one key in the group is enough. {npc:8888}'s ghost stands on his tomb in the hanging building, and only the dead see him. Whoever will carry the key: take off the gear (no repair bill), die in the lava under the chains, release, run back as a ghost from the graveyard and speak with {npc:8888}, then come back to life at the body or by a group mate's spell. To check in game."] = "La {item:11000} ouvre les portes des deuxième et troisième visites (les portes d'Ombreforge de la prison et {object:161460}) : une clé dans le groupe suffit. Le fantôme de {npc:8888} se tient sur son tombeau, dans le bâtiment suspendu, et seuls les morts le voient. Pour celui qui portera la clé : retirer l'équipement (pas de frais de réparation), mourir dans la lave sous les chaînes, libérer l'esprit, revenir en fantôme depuis le cimetière et parler à {npc:8888}, puis revenir à la vie près du corps ou par le sort d'un équipier. À vérifier en jeu.",
		["The {item:12382} opens the gate of the Gauntlet. Three ziggurats stand on the dead side, each with a guardian at its door: {npc:10437} (the first, on the left), {npc:10436} (the second: she possesses a player, bring them to half health), {npc:10438} (the third). Kill each guardian, then every {npc:10399} inside: the {item:13176} for {npc:11035} lies in a small box in one of the three. Stonespine (rare) may walk between the first two."] = "La {item:12382} ouvre la porte du Défilé (Gauntlet). Trois ziggourats se dressent du côté mort-vivant, chacune avec un gardien à sa porte : {npc:10437} (la première, sur la gauche), {npc:10436} (la deuxième : elle possède un joueur, l'amener à la moitié de sa vie), {npc:10438} (la troisième). Tuer chaque gardien, puis chaque {npc:10399} à l'intérieur : les {item:13176} pour {npc:11035} sont dans une petite boîte, dans l'une des trois. Stonespine (rare) peut passer entre les deux premières.",
		["The {item:13176}: a ziggurat of the dead side"] = "Les {item:13176} : une ziggourat du côté mort-vivant",
		["The {item:13704}"] = "La {item:13704}",
		["The {item:13704} (optional)"] = "La {item:13704} (facultative)",
		["The {item:13704} opens Scholomance: one player of the group with it is enough, and a rogue can pick the lock instead. Its chain is long: {npc:11056} at Chillwind Camp, {npc:5411} in Gadgetzan (15 gold), Fire Plume Ridge in {zone:1449} with two Thorium Bars, then {npc:1852} (elite 61) in Andorhal. Somebody in the group already has the key? Skip it."] = "La {item:13704} ouvre Scholomance : un joueur du groupe qui l'a suffit, et un voleur peut crocheter la serrure à la place. Sa suite est longue : {npc:11056} au camp du Noroît, {npc:5411} à Gadgetzan (15 pièces d'or), la Crête de la Fournaise dans le {zone:1449} avec deux barres de thorium, puis {npc:1852} (élite 61) à Andorhal. Quelqu'un du groupe a déjà la clé ? La passer.",
		["The {npc:14358} and his treasure"] = "{npc:14358} et son trésor",
		["Third visit, the dead side: the {object:175461}, the gate east of the main one, opens with the {item:12382} onto {object:175440}. Bosses 59 to 62: 60 advised. Opening the gate of the Gauntlet starts {npc:10440}'s 45-minute countdown: it only matters for {npc:16031} (Dead Man's Plea, a dungeon set quest), no quest of this guide depends on it."] = "Troisième visite, le côté mort-vivant : {object:175461}, la porte à l'est de la grande porte, s'ouvre avec la {item:12382} sur {object:175440}. Boss de 59 à 62 : niveau 60 conseillé. Ouvrir la porte du Défilé (Gauntlet) lance le compte à rebours de 45 minutes de {npc:10440} : il ne compte que pour {npc:16031} (Dead Man's Plea, une quête d'ensemble de donjon), aucune quête de ce guide n'en dépend.",
		["To Chillwind Camp: the flight from Light's Hope Chapel, or the road south from {npc:1855}'s hut. {npc:11023} stands in the camp: his family's fortune is four deeds, all in Scholomance."] = "Jusqu'au Camp du Noroît : le vol depuis la chapelle de l'Espoir de Lumière, ou la route vers le sud depuis la cabane de {npc:1855}. {npc:11023} se tient dans le camp : la fortune de sa famille, ce sont quatre titres de propriété, tous dans la Scholomance.",
		["To Chillwind Camp: the flight from Light's Hope Chapel, or the road south from {npc:1855}'s hut. {npc:11056} stands in the camp."] = "Vers le camp du Noroît : le vol depuis la chapelle de l'Espoir de Lumière, ou la route vers le sud depuis la cabane de {npc:1855}. {npc:11056} se tient dans le camp.",
		["Two Thorium Bars in the bags (a miner, or the auction house). Ride west from Gadgetzan into {zone:1449} and climb Fire Plume Ridge in its middle: use the {item:14644} by the lava lake at the top. The Living Blazes up there are 54-55."] = "Deux barres de thorium dans les sacs (un mineur, ou l'hôtel des ventes). Partir à l'ouest de Gadgetzan vers le {zone:1449} et grimper sur la Crête de la Fournaise en son centre : utiliser le {item:14644} près du lac de lave au sommet. Les Brasiers vivants là-haut sont de niveau 54-55.",
		["Walk back out of Scholomance, without resetting the instance: Eva stands at the door. Her next quest is {npc:10503}'s, near the entrance."] = "Ressortir de la Scholomance à pied, sans réinitialiser l'instance : Eva se tient à la porte. Sa quête suivante est celle de {npc:10503}, près de l'entrée.",
		["Warpwood Quarter: {npc:11492}"] = "Aile est : {npc:11492}",
		["Warpwood Quarter: {npc:14327}"] = "Aile est : {npc:14327}",
		["Warpwood Quarter: {npc:14354}"] = "Aile est : {npc:14354}",
		["West Garrison and the Manufactory"] = "Garnison ouest et manufacture",
		["West of Terrordale, {npc:1855}'s hut on the bank of the border river. His next quest, Find Myranda, leads to Hearthglen: not in this guide."] = "À l'ouest de Val-Terreur, la cabane de {npc:1855} sur la rive de la rivière frontière. Sa quête suivante, Find Myranda, mène à Âtreval : pas dans ce guide.",
		["West of Terrordale, {npc:1855}'s hut on the bank of the border river. {quest:5846} follows {quest:5845}, done on the route: it goes to {npc:11936}, on Caer Darrow in the lake of the {zone:1422}, whose own quest is a painting in Stratholme."] = "À l'ouest de Val-Terreur, la cabane de {npc:1855} au bord de la rivière frontière. {quest:5846} suit {quest:5845}, faite sur le parcours : elle va à {npc:11936}, à Caer Darrow sur le lac des {zone:1422}, dont la quête suivante est un tableau caché dans Stratholme.",
		["What is left of Blackrock Depths in the quest log is for another run: keep it for one, or abandon it to free the log (right-click it in the quest log)."] = "Ce qui reste des Profondeurs de Rochenoire dans le journal de quêtes est pour une autre fois : le garder pour une autre visite, ou l'abandonner pour libérer le journal (clic droit sur la quête dans le journal).",
		["What is left of Dire Maul in the quest log is for another run: keep it for one, or abandon it to free the log (right-click it in the quest log)."] = "Ce qui reste de Hache-Tripes dans le journal de quêtes est pour une autre fois : le garder pour une autre visite, ou l'abandonner pour libérer le journal (clic droit sur la quête dans le journal).",
		["What is left of Lower Blackrock Spire in the quest log is for another run: keep it for one, or abandon it to free the log (right-click it in the quest log).\nUpper Blackrock Spire, up the stairs on the left past the Spire's entrance, is not in this guide: a dungeon made for a raid group of ten. Upper Blackrock Spire takes no key on Forever (the {item:12344} quest no longer rewards it)."] = "Ce qui reste du pic Rochenoire inférieur dans le journal de quêtes est pour une autre fois : le garder pour une autre visite, ou l'abandonner pour libérer le journal (clic droit sur la quête dans le journal).\nLe pic Rochenoire supérieur, en haut de l'escalier à gauche après l'entrée du pic, n'est pas dans ce guide : un donjon fait pour un groupe de raid de dix. Sur Forever, il ne demande aucune clé (la quête du {item:12344} ne le donne plus).",
		["What is left of Scholomance in the quest log is for another run: keep it for one, or abandon it to free the log (right-click it in the quest log)."] = "Ce qui reste de la Scholomance dans le journal de quêtes est pour une autre fois : le garder pour une autre visite, ou l'abandonner pour libérer le journal (clic droit sur la quête dans le journal).",
		["What is left of Stratholme in the quest log is for another run: keep it for one, or abandon it to free the log (right-click it in the quest log)."] = "Ce qui reste de Stratholme dans le journal de quêtes est pour une autre fois : le garder pour une autre visite, ou l'abandonner pour libérer le journal (clic droit sur la quête dans le journal).",
		["{item:11230}: the molt on {npc:9016}'s remains"] = "{item:11230} : le cuir altéré sur les restes de {npc:9016}",
		["{item:13176}: a small box in one of the ziggurats"] = "{item:13176} : une petite boîte dans l'une des ziggourats",
		["{item:13448}: beside {npc:10504}"] = "{item:13448} : à côté de {npc:10504}",
		["{item:13450}: the Reliquary"] = "{item:13450} : le Reliquaire",
		["{item:13451}: past the Chamber of Summoning"] = "{item:13451} : après la Chambre d'invocation",
		["{item:13471}: the Laboratory"] = "{item:13471} : le Laboratoire",
		["{item:13920}: keep it"] = "{item:13920} : la garder",
		["{item:18540}: a {item:18501} in the {item:22201}"] = "{item:18540} : un {item:18501} dans le {item:22201}",
		["{npc:10220} and {npc:10268}"] = "{npc:10220} et {npc:10268}",
		["{npc:10220}, for {quest:4701}"] = "{npc:10220}, pour {quest:4701}",
		["{npc:10440} (elite 62) raises skeletons and his Unholy Aura hurts everyone near him; his Mortal Strike cuts the tank's healing. His head is for Duke Nicholas. Then speak with {npc:10917} for {quest:5125}. The glowing symbol in front of the Baron, {object:176631}, belongs to {npc:10508}'s chain: not in this guide."] = "{npc:10440} (élite 62) relève des squelettes et son Aura impie blesse tous ceux qui l'approchent ; sa Frappe mortelle réduit les soins reçus par le tank. Sa tête est pour le duc Nicholas. Parler ensuite à {npc:10917} pour {quest:5125}. Le symbole lumineux devant le baron, {object:176631}, appartient à la chaîne de {npc:10508} : pas dans ce guide.",
		["{npc:10811} (elite 60) holds his library, across the hall from the last chamber, {npc:10813}'s: spread out against his fire. Once he is dead, use the {object:176245}, the book on the table behind him: the room burns. Leave {npc:10813} for the second visit."] = "{npc:10811} (élite 60) tient sa bibliothèque, en face de la dernière salle, celle de {npc:10813} : s'écarter les uns des autres contre son feu. Une fois qu'il est mort, utiliser {object:176245}, le livre sur la table derrière lui : la salle prend feu. Laisser {npc:10813} pour la deuxième visite.",
		["{npc:10917} stands by the Baron's body once the fight is over: speak with him for the reward."] = "{npc:10917} se tient près du corps du baron une fois le combat fini : lui parler pour la récompense.",
		["{npc:10917} waits in Alonsus Chapel, on {object:175440}: the player with the {item:12845} hands it in, then takes {quest:5125}. With the medallion handed in during this instance, {npc:10917} joins the fight against {npc:10440}. Whether he offers {quest:5125} to the others of the group too: to check in game."] = "{npc:10917} attend dans la chapelle d'Alonsus, sur {object:175440} : le joueur qui a le {item:12845} le lui rend, puis prend {quest:5125}. Le médaillon rendu dans cette instance, {npc:10917} rejoint le combat contre {npc:10440}. Propose-t-il aussi {quest:5125} aux autres membres du groupe ? À vérifier en jeu.",
		["{npc:10917}, after the fight"] = "{npc:10917}, après le combat",
		["{npc:10917}: with the {item:12845}"] = "{npc:10917} : avec le {item:12845}",
		["{npc:11036} stands inside the chapel; {npc:11035}, {npc:11039} and {npc:11033} stand around it."] = "{npc:11036} se tient dans la chapelle ; {npc:11035}, {npc:11039} et {npc:11033} se tiennent autour.",
		["{npc:11039}: the head of {npc:10813}"] = "{npc:11039} : la tête de {npc:10813}",
		["{npc:11056}: for {npc:5411} in Gadgetzan"] = "{npc:11056} : pour {npc:5411} à Gadgetzan",
		["{npc:11496} and {npc:11486}"] = "{npc:11496} et {npc:11486}",
		["{npc:11801}'s house stands in Nighthaven."] = "La maison de {npc:11801} se trouve à Havrenuit.",
		["{npc:11936}, inside"] = "{npc:11936}, à l'intérieur",
		["{npc:14327} (elite 57), a blood elf warlock, fights with her imp Pimgib: interrupt her spells. Her web is for {npc:7877}."] = "{npc:14327} (élite 57), une démoniste elfe de sang, se bat avec son diablotin Pimgib : interrompre ses sorts. Sa toile est pour {npc:7877}.",
		["{npc:14354} the imp waits by the entrance: speak with him, then chase him through the first rooms, speaking with him each time he stops. He ends on a platform up a ramp near the back door, where he fights (elite 57). He drops {npc:14355}'s {item:18261} and the {item:18249}, which opens the western and northern wings: one key in the group is enough."] = "{npc:14354} le diablotin attend près de l'entrée : lui parler, puis le poursuivre à travers les premières salles, en lui reparlant à chaque arrêt. Il finit sur une plate-forme en haut d'une rampe près de la porte de derrière, où il se bat (élite 57). Il donne le {item:18261} de {npc:14355} et la {item:18249}, qui ouvre les ailes ouest et nord : une clé dans le groupe suffit.",
		["{npc:14358}: the same quest, the other version"] = "{npc:14358} : la même quête, l'autre version",
		["{npc:1748} is in the throne room at the back of {object:2117}, {npc:1749} at his side: speak with her, then with him again."] = "{npc:1748} est dans la salle du trône, au fond de {object:2117}, {npc:1749} à ses côtés : lui parler, puis reparler à Bolvar.",
		["{npc:1749}: speak with her"] = "{npc:1749} : lui parler",
		["{npc:2784}: {npc:9021} is a prisoner in Blackrock Depths"] = "{npc:2784} : {npc:9021} est prisonnier dans les Profondeurs de Rochenoire",
		["{npc:7877} stands in the fort; {npc:14374} walks the road through it."] = "{npc:7877} se tient dans le fort ; {npc:14374} parcourt la route qui le traverse.",
		["{npc:8888} (one player is enough)"] = "{npc:8888} (un joueur suffit)",
		["{npc:8888}, as a ghost"] = "{npc:8888}, en fantôme",
		["{npc:9017}, for {quest:4263}"] = "{npc:9017}, pour {quest:4263}",
		["{npc:9017}, in the dungeon: second visit"] = "{npc:9017}, dans le donjon : deuxième visite",
		["{npc:9019} (elite 59) and {npc:8929}. {quest:4362}: kill the Emperor WITHOUT killing Moira, who heals him: one player keeps her busy and interrupts her, everyone else on the Emperor. She then stops fighting: speak with her."] = "{npc:9019} (élite 59) et {npc:8929}. {quest:4362} : tuer l'empereur SANS tuer Moira, qui le soigne : un joueur l'occupe et l'interrompt, tous les autres sur l'empereur. Elle cesse alors de combattre : lui parler.",
		["{npc:9019}, for {quest:4362}"] = "{npc:9019}, pour {quest:4362}",
		["{npc:9056} (elite 54) walks up and down the winding ramp of the Hall of Crafting: clear the ramp first, interrupt his Holy Light. He drops {item:10999} for every player on {quest:3802}."] = "{npc:9056} (élite 54) monte et descend la rampe en spirale de la salle des artisans (Hall of Crafting) : nettoyer la rampe d'abord, interrompre sa Lumière sacrée. Il donne {item:10999} à chaque joueur qui a {quest:3802}.",
		["{npc:9156} and the Seven"] = "{npc:9156} et les Sept",
		["{npc:9177}, {npc:9561}, {npc:9562} and {npc:9560} stand in the camp. {quest:4262} is outside the dungeon, on the way in; Incendius, inside, comes after him."] = "{npc:9177}, {npc:9561}, {npc:9562} et {npc:9560} se tiennent dans le camp. {quest:4262} se fait hors du donjon, sur le chemin ; Incendius, dedans, vient après.",
		["{npc:9177}: the fanny packs drop all through the dungeon"] = "{npc:9177} : les sacoches tombent dans tout le donjon",
		["{npc:9196}, for {quest:5081}"] = "{npc:9196}, pour {quest:5081}",
		["{npc:9237}, for {quest:5081}"] = "{npc:9237}, pour {quest:5081}",
		["{npc:9459} hands over an {item:11231} with the quest: it goes on {npc:9016}'s remains, in the dungeon (second visit)."] = "{npc:9459} remet un {item:11231} avec la quête : il sert sur les restes de {npc:9016}, dans le donjon (deuxième visite).",
		["{npc:9459}: the {npc:9461}"] = "{npc:9459} : le {npc:9461}",
		["{npc:9562}'s chain ({quest:4182} done) leads to {quest:4241}, a prisoner in Blackrock Depths: first a round trip to Lakeshire and {zone:1453}, by flight."] = "La suite de {npc:9562} ({quest:4182} faite) mène à {quest:4241}, prisonnier dans les Profondeurs de Rochenoire : d'abord un aller-retour à Comté-du-Lac et à {zone:1453}, en vol.",
		["{npc:9563}: let him milk you"] = "{npc:9563} : se laisser traire",
		["{npc:9563}: speak with him, to the end of his story"] = "{npc:9563} : lui parler, jusqu'au bout de son histoire",
		["{npc:9568}, for {quest:5081}"] = "{npc:9568}, pour {quest:5081}",
		["{object:175433} and {object:175440}"] = "{object:175433} et {object:175440}",
		["{object:176245}: set it on fire"] = "{object:176245} : y mettre le feu",
		["{object:179517}, under the ramp of the Athenaeum"] = "{object:179517}, sous la rampe de l'Athénée",
		["{object:179565}; inside"] = "{object:179565} ; à l'intérieur",
		["{object:2117}: Bolvar and Lady Prestor"] = "{object:2117} : Bolvar et Lady Prestor",
		["{quest:4022}, first part (a group quest on the route at 50): {npc:9459} hides in a cave in the far east of the Steppes. The {npc:9461} (elite 54) appears outside it and drops the molt."] = "{quest:4022}, première partie (une quête de groupe du parcours à 50) : {npc:9459} se cache dans une grotte tout à l'est des Steppes. Le {npc:9461} (élite 54) apparaît devant et laisse tomber la mue.",
		["{quest:4123}: the {object:161495}"] = "{quest:4123} : {object:161495}",
		["{quest:4241}'s chain starts with {npc:9562}'s {quest:4182}: the black dragonkin of the hills east of Flame Crest and of the eastern edge of the Steppes, elite at around 52."] = "La suite de {quest:4241} commence par {quest:4182} de {npc:9562} : les draconiens noirs des collines à l'est de la Corniche des flammes et du bord est des Steppes, élites vers 52.",
		["{quest:4262}: the Grinding Quarry, before the dungeon's door"] = "{quest:4262} : la carrière (Grinding Quarry), avant la porte du donjon",
		["{quest:4264}: Anvilrage dwarves"] = "{quest:4264} : nains Anvilrage",
		["{quest:4341}: listen to his whole story"] = "{quest:4341} : écouter toute son histoire",
		["{quest:4361}: Magni then asks you to save Princess Moira, the Emperor's prisoner at the bottom of the dungeon (third visit)."] = "{quest:4361} : Magni demande ensuite de sauver la princesse Moira, prisonnière de l'empereur au fond du donjon (troisième visite).",
		["{quest:4701}: {npc:10220}, the great worg of the Spire. {npc:9560}'s own quest comes later, through {npc:10257}, a goblin hidden in the dungeon."] = "{quest:4701} : {npc:10220}, la grande worg du Pic. La quête de {npc:9560} vient plus tard, par {npc:10257}, une gobeline cachée dans le donjon.",
		["{quest:4867} needs a {item:12533}: they lean against the wall behind the Scarshield orcs, past the bridge out of Hordemar City. Then the Spirestone ogres: {npc:9196} (elite 59) and his two guards. His head is for the Urok event: one player with the quest carries the pike and the head."] = "{quest:4867} demande une {item:12533} : elles sont appuyées contre le mur derrière les orcs Scarshield, après le pont qui sort de la cité de Hordemar. Puis les ogres Spirestone : {npc:9196} (élite 59) et ses deux gardes. Sa tête sert pour l'événement d'Urok : un joueur qui a la quête porte la pique et la tête.",
		["{quest:5001}: a small chest at the bottom of Hordemar City"] = "{quest:5001} : un petit coffre au fond de la cité de Hordemar",
		["{quest:5002}: out and back"] = "{quest:5002} : aller-retour",
		["{quest:5251} handed in: {npc:10813}'s head now starts the next quest (second visit)."] = "{quest:5251} rendue : la tête de {npc:10813} lance maintenant la quête suivante (deuxième visite).",
		["{quest:5263}: Duke Nicholas sends you to {quest:5264}, inside the chapel, who opens the {object:176317}, the chest beside him, for your reward."] = "{quest:5263} : le duc Nicholas envoie voir {quest:5264}, dans la chapelle, qui ouvre {object:176317}, le coffre à côté de lui, pour la récompense.",
		["{quest:5526} (optional)"] = "{quest:5526} (facultative)",
		["{quest:5526} is not done and the guide does not go back to Dire Maul: keep it for a run of your own, or abandon it to free the log (right-click it in the quest log)."] = "{quest:5526} n'est pas finie et le guide ne retourne pas à Hache-Tripes : la garder pour une visite à part, ou l'abandonner pour libérer le journal (clic droit sur la quête dans le journal).",
		["{quest:5526}: not done"] = "{quest:5526} : pas finie",
		["{quest:5526}: {npc:11801}, in her house in Nighthaven. From Feathermoon, the flight to {zone:1450}."] = "{quest:5526} : {npc:11801}, dans sa maison de Havrenuit. Depuis le bastion de Plumelune, le vol jusqu'à {zone:1450}.",
		["{quest:5529}: the dragon whelps of Scholomance. {npc:11035}'s other Scholomance quest, {item:12368}, comes only after {npc:10267}'s chain through Upper Blackrock Spire: not in this guide."] = "{quest:5529} : les dragonnets de la Scholomance. L'autre quête de {npc:11035} pour la Scholomance, {item:12368}, ne vient qu'après la chaîne de {npc:10267}, qui passe par le pic Rochenoire supérieur : pas dans ce guide.",
		["{quest:5529}: the flight from Chillwind Camp to Light's Hope Chapel. A {quest:5582} in the bags? Once {quest:5529} is handed in, right-click it: its quest goes back to {npc:11035} at once."] = "{quest:5529} : le vol du Camp du Noroît jusqu'à la chapelle de l'Espoir de Lumière. Une {quest:5582} dans les sacs ? Une fois {quest:5529} rendue, clic droit dessus : sa quête se rend à {npc:11035} tout de suite.",
		["{quest:5582}, if one dropped"] = "{quest:5582}, si elle est tombée",
		["{quest:5848} is not done and the guide does not go back to Stratholme: keep it for a run of your own, or abandon it to free the log (right-click it in the quest log)."] = "{quest:5848} n'est pas finie et le guide ne retourne pas à Stratholme : la garder pour une visite à part, ou l'abandonner pour libérer le journal (clic droit sur la quête dans le journal).",
		["{quest:5848}: an {object:177287} hangs on the wall of Galford's library, the twin moons on it; Renfray's painting is hidden behind it."] = "{quest:5848} : un {object:177287} est accroché au mur de la bibliothèque de Galford, les deux lunes dessus ; le tableau de Renfray est caché derrière.",
		["{quest:5848}: behind the {object:177287}"] = "{quest:5848} : derrière le {object:177287}",
		["{quest:5848}: not done"] = "{quest:5848} : pas finie",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
} end)()
t.guides["groupe-alliance/brassenoire"] = (function() return {
		["Auberdine"] = "Auberdine",
		["Auberdine: {npc:8997}"] = "Auberdine : {npc:8997}",
		["Back down the portal to Rut'theran Village, then the flight to Auberdine."] = "Redescendre par le portail au village de Rut'theran, puis le vol pour Auberdine.",
		["Back to Auberdine"] = "Retour à Auberdine",
		["Blackfathom Deeps"] = "Profondeurs de Brassenoire",
		["Blackfathom Deeps: a 5-player dungeon on the north-west coast of {zone:1440}, levels 24 to 32 in the group finder: at 25 or more it goes well. Its quests are taken here and in {zone:1457}, the dungeon is run from the Zoram Strand, and they are handed in back here."] = "Profondeurs de Brassenoire : un donjon pour 5 joueurs sur la côte nord-ouest d'{zone:1440}, niveaux 24 à 32 dans la recherche de groupe : à 25 ou plus, il passe bien. Ses quêtes se prennent ici et à {zone:1457}, le donjon se fait depuis la grève de Zoram, et elles se rendent ici au retour.",
		["Blackfathom Deeps: along the way"] = "Profondeurs de Brassenoire : en chemin",
		["Blackfathom Deeps: before going in"] = "Profondeurs de Brassenoire : avant d'entrer",
		["Blackfathom Deeps: {npc:4787}"] = "Profondeurs de Brassenoire : {npc:4787}",
		["Blackfathom Deeps: {npc:4787} (without the {zone:1457} quest)"] = "Profondeurs de Brassenoire : {npc:4787} (sans la quête de {zone:1457})",
		["Blackfathom Deeps: {npc:4831} and {npc:6243}"] = "Profondeurs de Brassenoire : {npc:4831} et {npc:6243}",
		["Blackfathom Deeps: {npc:4832}"] = "Profondeurs de Brassenoire : {npc:4832}",
		["Blackfathom Deeps: {npc:4887}'s pool"] = "Profondeurs de Brassenoire : le bassin de {npc:4887}",
		["Collected all through the dungeon: the brain stems from the nagas and the Fallenroot satyrs (those outside the portal drop them too), the Twilight Pendants from the Twilight's Hammer cultists, about 4 kills in 5 for each. Every player with the quest loots their own; with a full group on them, a second run may be needed."] = "À ramasser dans tout le donjon : les troncs cérébraux sur les nagas et les satyres (ceux d'avant le portail en lâchent aussi), les pendentifs du Crépuscule sur les cultistes du Marteau du crépuscule, environ 4 fois sur 5 pour chacun. Chaque joueur qui a la quête ramasse les siens ; avec tout le groupe dessus, un second passage peut être nécessaire.",
		["Dungeon · Blackfathom Deeps (23-28)"] = "Donjon · Profondeurs de Brassenoire (23-28)",
		["From Auberdine to Rut'theran Village: the flight, or the boat from the Auberdine dock for whoever never learned that flight path; then the portal up to {zone:1457}. {npc:4783} and {npc:4784} stand with the {object:92525}."] = "D'Auberdine au village de Rut'theran : le vol, ou le bateau du quai d'Auberdine pour qui n'a jamais appris ce trajet ; puis le portail qui monte à {zone:1457}. {npc:4783} et {npc:4784} se tiennent avec {object:92525}.",
		["From Auberdine to Rut'theran Village: the flight, or the boat from the Auberdine dock for whoever never learned that flight path; then the portal up to {zone:1457}. {npc:4784} stands with the {object:92525}."] = "D'Auberdine au village de Rut'theran : le vol, ou le bateau du quai d'Auberdine pour qui n'a jamais appris ce trajet ; puis le portail qui monte à {zone:1457}. {npc:4784} se tient avec {object:92525}.",
		["Hearthstone to Auberdine"] = "Pierre de foyer vers Auberdine",
		["In the log before going in: {quest:1275} ({npc:8997}, Auberdine); {quest:1198} and {quest:1199} for whoever went to {zone:1457}. Share each quest with the group: click it in the quest log, then Share."] = "Dans le journal avant d'entrer : {quest:1275} ({npc:8997}, Auberdine) ; {quest:1198} et {quest:1199} pour qui est allé à {zone:1457}. Partager chaque quête avec le groupe : clic sur la quête dans le journal, puis Partager.",
		["Keep 5 free quest log slots. Bind your hearthstone at the inn: it brings you back here after the dungeon."] = "Garder 5 places libres dans le journal. Lier la pierre de foyer à l'auberge : elle ramène ici après le donjon.",
		["Kelris waits in the ceremonial chamber before the last room. Interrupt his Sleep and kill his adds first. Every player on {quest:1200} loots their own head. {npc:4829}, behind him, is optional: no quest, good loot."] = "Kelris attend dans la salle de cérémonie avant la dernière salle. Interrompre son Sommeil et tuer ses aides d'abord. Chaque joueur qui a {quest:1200} ramasse sa propre tête. {npc:4829}, derrière lui, est facultatif : pas de quête, du bon butin.",
		["Out by the portal, then the hearthstone: it was bound in Auberdine at the start of the chapter. On cooldown? Ride back north along the coast."] = "Sortie par le portail, puis la pierre de foyer : elle a été liée à Auberdine au début du chapitre. En recharge ? Remonter vers le nord le long de la côte.",
		["Paladins: {quest:1442}"] = "Paladins : {quest:1442}",
		["South along the coast road out of {zone:1439}, then the {zone:1440} shore to the Zoram Strand, its north end: about ten minutes' ride. The way in is the sunken ruins' pit at the north end of the strand: down the stairs, then swim through the tunnels under the wall, past the blue crystals, to the portal. Every enemy inside is elite."] = "Vers le sud par la route côtière de {zone:1439}, puis la rive d'{zone:1440} jusqu'au nord de la grève de Zoram : une dizaine de minutes. L'entrée est la fosse des ruines englouties au nord de la grève : descendre l'escalier, puis nager dans les tunnels sous le mur, passé les cristaux bleus, jusqu'au portail. Tous les ennemis à l'intérieur sont élites.",
		["Thaelrid of the {object:92525} waits in an underwater cave whose entrance is south-east of {npc:4887}'s pool. He offers {quest:1200} without {quest:1198} too. Talk to him BEFORE killing Kelris; not offered? Carry on."] = "Thaelrid, de {object:92525}, attend dans une grotte sous l'eau dont l'entrée est au sud-est du bassin de {npc:4887}. Il propose {quest:1200} même sans {quest:1198}. Lui parler AVANT de tuer Kelris ; pas proposée ? Continuer.",
		["Thaelrid of the {object:92525} waits in an underwater cave whose entrance is south-east of {npc:4887}'s pool. Talk to him BEFORE killing Kelris: Kelris's head drops only for players who already hold {quest:1200}."] = "Thaelrid, de {object:92525}, attend dans une grotte sous l'eau dont l'entrée est au sud-est du bassin de {npc:4887}. Lui parler AVANT de tuer Kelris : la tête de Kelris ne tombe que pour les joueurs qui ont déjà {quest:1200}.",
		["The great turtle {npc:4887} lives in the first big pool. {npc:4787} waits by a campfire in an underwater side cave, its entrance south-east of the same pool (next step)."] = "La grande tortue {npc:4887} vit dans le premier grand bassin. {npc:4787} attend près d'un feu de camp dans une grotte sous-marine voisine, dont l'entrée est au sud-est du même bassin (étape suivante).",
		["Two more Blackfathom quests wait in {zone:1457}, with the {object:92525}: {quest:1198}, then {quest:1200} from Thaelrid inside the dungeon, and {quest:1199}. About 19,600 XP with the hand-ins, and a blue reward. The detour: the boat from the Auberdine dock to Rut'theran Village (Night Elves fly), the portal up to {zone:1457}, then back; the hand-ins need the same trip after the dungeon. Short on time? Skip it."] = "Deux autres quêtes de Brassenoire attendent à {zone:1457}, chez l'{object:92525} : {quest:1198}, puis {quest:1200} donnée par Thaelrid dans le donjon, et {quest:1199}. Environ 19 600 XP avec les rendus, et une récompense bleue. Le détour : le bateau du quai d'Auberdine pour le village de Rut'theran (les elfes de la nuit volent), le portail qui monte à {zone:1457}, puis le retour ; les rendus demandent le même trajet après le donjon. Peu de temps ? Le passer.",
		["Warlocks: {quest:1740}"] = "Démonistes : {quest:1740}",
		["{npc:4784}, with the 10 pendants"] = "{npc:4784}, avec les 10 pendentifs",
		["{npc:4831}, the second boss, comes with two guards: interrupt her Forked Lightning, it chains between players standing close (spread out). {npc:6243}, the murloc of the side cave, is optional: pull his murlocs one at a time; the stone behind him gives the Blessing of Blackfathom. The Twilight's Hammer cultists come after them."] = "{npc:4831}, le deuxième boss, vient avec deux gardes : interrompre son Éclair fourchu, qui rebondit entre les joueurs proches (s'écarter). {npc:6243}, le murloc de la grotte latérale, est facultatif : tirer ses murlocs un par un ; la pierre derrière lui donne la Bénédiction de Brassenoire. Les cultistes du Marteau du crépuscule viennent ensuite.",
		["{quest:1442}, for Paladins: the Blackfathom Tide Priestesses, Oracles and Sea Witches (the naga casters) drop the {item:6995}, about 1 in 2. {npc:3649} in Auberdine cleanses it, on the way back."] = "{quest:1442}, pour les paladins : les prêtresses des marées, oracles et sorcières des mers de Brassenoire (les nagas lanceuses de sorts) lâchent la {item:6995}, environ 1 fois sur 2. {npc:3649}, à Auberdine, la purifie au retour.",
		["{zone:1457}: Blackfathom hand-ins (detour)"] = "{zone:1457} : rendus de Brassenoire (détour)",
		["{zone:1457}: the {object:92525} (Blackfathom Deeps, optional detour)"] = "{zone:1457} : {object:92525} (Profondeurs de Brassenoire, détour facultatif)",
		["{zone:1457}: {quest:1199} (detour)"] = "{zone:1457} : {quest:1199} (détour)",
} end)()
t.guides["groupe-alliance/kraal-de-tranchebauge"] = (function() return {
		["Dungeon · Razorfen Kraul (29-37)"] = "Donjon · Kraal de Tranchebauge (29-37)",
		["Escort him out of the Kraul"] = "L'escorter hors du kraal",
		["Jump down from {npc:4421}'s area and kill a few quilboars: {npc:4510}, a night elf who died in the Kraul, lies by a tent in the north of that area. {quest:1142} asks for {item:5825}, about 1 quilboar in 10, for each player on the quest: by now most of the Kraul is cleared, so it often takes the walk back or a second run. Its hand-in is in {zone:1457}, off the route: whenever the player is there, Polestar lists it."] = "Sauter depuis le repaire de {npc:4421} et tuer quelques huttiers : {npc:4510}, une elfe de la nuit morte dans le Kraal, gît près d'une tente au nord de cette zone. {quest:1142} demande le {item:5825}, environ 1 huttier sur 10, pour chaque joueur qui a la quête : le Kraal est alors presque vidé, il faut donc souvent le chemin du retour ou un second passage. Elle se rend à {zone:1457}, hors du parcours : Polestar l'affiche dès que le joueur y passe.",
		["Keep 3 free quest log slots."] = "Garder 3 places libres dans le journal.",
		["Not there? Another group is escorting him: wait for him to come back, or join them."] = "Pas là ? Un autre groupe l'escorte : attendre son retour, ou se joindre à eux.",
		["Polestar asks whether to do this escort: in a group, answer Do it (Skip it takes the quest out of the chapter)."] = "Polestar demande s'il faut faire cette escorte : en groupe, répondre « La faire » (« La passer » retire la quête du chapitre).",
		["Razorfen Kraul"] = "Kraal de Tranchebauge",
		["Razorfen Kraul entrance"] = "Entrée du Kraal de Tranchebauge",
		["Razorfen Kraul: {npc:4421}"] = "Kraal de Tranchebauge : {npc:4421}",
		["Razorfen Kraul: {npc:4508}'s reward"] = "Kraal de Tranchebauge : la récompense de {npc:4508}",
		["Razorfen Kraul: {npc:4510}"] = "Kraal de Tranchebauge : {npc:4510}",
		["Razorfen Kraul: {quest:1144}"] = "Kraal de Tranchebauge : {quest:1144}",
		["Roogug, {npc:4424}, {npc:4428}, {npc:4420} and {npc:4422} come before her (the codex's order). {npc:4421}, the last boss, fights on the ramp outside her hut and teleports back into it now and then: the tank grabs her again. Her Purity dispels every debuff and makes her immune for a while: no damage-over-time on her. Each player on {quest:1101} loots the medallion."] = "Roogug, {npc:4424}, {npc:4428}, {npc:4420} et {npc:4422} viennent avant elle (l'ordre du codex). {npc:4421}, le dernier boss, combat sur la rampe devant sa hutte et s'y téléporte de temps en temps : le tank la reprend. Sa Pureté dissipe tous les effets négatifs et la rend insensible un moment : pas de dégâts sur la durée sur elle. Chaque joueur qui a {quest:1101} ramasse le médaillon.",
		["Shamans: {quest:96264}"] = "Chamans : {quest:96264}",
		["Warriors: {quest:1701}"] = "Guerriers : {quest:1701}",
		["{item:5825}: quilboars of the Kraul, about 1 in 10"] = "{item:5825} : huttes-épines du kraal, environ 1 fois sur 10",
		["{npc:4048}: back to the route"] = "{npc:4048} : retour au parcours",
		["{quest:1144} and {npc:4510} give their quests inside, at the end: nothing else to take beforehand. Share {quest:1101} with the group: click it in the quest log, then Share."] = "{quest:1144} et {npc:4510} donnent leurs quêtes à l'intérieur, à la fin : rien d'autre à prendre avant. Partager {quest:1101} avec le groupe : clic sur la quête dans le journal, puis Partager.",
		["{quest:1144} gives the reward himself, at the entrance, once he is safe."] = "{quest:1144} donne la récompense lui-même, à l'entrée, une fois en sécurité.",
		["{quest:1144}, a goblin, is held in the same tent as {npc:4510}. Everyone takes his quest before he starts walking; he walks back to the entrance by the south side, past many armored boars. He gives the reward himself at the end."] = "{quest:1144}, un gobelin, est retenu dans la même tente que {npc:4510}. Chacun prend sa quête avant qu'il se mette en marche ; il retourne à l'entrée par le côté sud, devant de nombreux sangliers cuirassés. Il donne lui-même la récompense à la fin.",
		["{quest:1144}, at the entrance"] = "{quest:1144}, à l'entrée",
		["{quest:1701}, for Warriors: Roogug, the first boss, drops the {item:6841}. The other items of the quest come from Stonetalon and the {zone:1437}: Polestar's class guides (Fire Hardened Armor) cover them."] = "{quest:1701}, pour les guerriers : Roogug, le premier boss, lâche la {item:6841}. Les autres objets de la quête viennent des Serres-Rocheuses et des {zone:1437} : les guides de classe de Polestar (Fire Hardened Armor) les couvrent.",
		["{quest:96264} ({npc:259023}, {zone:1417}): the {item:274463} comes from {npc:4421}. To check in game: the drop rate is not known."] = "{quest:96264} ({npc:259023}, {zone:1417}) : la {item:274463} vient de {npc:4421}. À vérifier en jeu : le taux de butin n'est pas connu.",
} end)()
t.guides["groupe-alliance/maraudon"] = (function() return {
		["Back out and in through the purple portal: {npc:12236}, at the end of this side, drops the {item:17703}."] = "Ressortir et entrer par le portail violet : {npc:12236}, au bout de ce côté, lâche le {item:17703}.",
		["Collected all through the dungeon: the Theradric Crystal Carvings, from the centaurs, satyrs and dryads and from most bosses. Every player with the quest loots their own."] = "À ramasser dans tout le donjon : les gravures de cristal théradrique, sur les centaures, les satyres, les dryades et la plupart des boss. Chaque joueur qui a la quête ramasse les siennes.",
		["Dungeon · Maraudon (46-51)"] = "Donjon · Maraudon (46-51)",
		["In the inner part, {npc:12225}: once beaten, he comes back as {npc:13716}. Hand him {quest:7044}; his next quest cannot be shared: each player takes it, then waits while he makes the scepter and speaks with him again."] = "Dans la partie intérieure, {npc:12225} : une fois vaincu, il revient en {npc:13716}. Lui rendre {quest:7044} ; sa quête suivante ne se partage pas : chaque joueur la prend, attend qu'il ait fabriqué le sceptre et lui parle de nouveau.",
		["Maraudon"] = "Maraudon",
		["Maraudon: Celebras"] = "Maraudon : Celebras",
		["Maraudon: along the way"] = "Maraudon : en chemin",
		["Maraudon: before going in"] = "Maraudon : avant d'entrer",
		["Maraudon: quests not done"] = "Maraudon : quêtes pas faites",
		["Maraudon: the Earth Song Falls"] = "Maraudon : la cascade de la partie intérieure",
		["Maraudon: the caves of the centaurs' sacred ground in western {zone:1443}, for a group of 5, levels 46 to 55 in the group finder: at 46 it takes a solid group, from about 48 it goes well. A long dungeon: two wings, then the inner part, whose last boss is 51. Woodwyrd, the treant in the middle of the Forlorn Gardens, wants water from inside it."] = "Maraudon : les grottes de la terre sacrée des centaures, à l'ouest de la {zone:1443}, pour un groupe de 5, niveaux 46 à 55 dans la recherche de groupe : à 46, il faut un groupe solide, à partir de 48 environ il passe bien. Un long donjon : deux ailes, puis la partie intérieure, dont le dernier boss est de niveau 51. Woodwyrd, le tréant au milieu des Forlorn Gardens, veut de l'eau de l'intérieur.",
		["Maraudon: the orange side"] = "Maraudon : le côté orange",
		["Maraudon: the purple side"] = "Maraudon : le côté violet",
		["Maraudon: {npc:12201}"] = "Maraudon : {npc:12201}",
		["North again along the road: {npc:13656} at Kormek's Hut."] = "De nouveau au nord par la route : {npc:13656} à la hutte de Kormek.",
		["North up the road to the night elf outpost. {npc:11715}'s quest cannot be shared: each player takes it here, with its {item:17693}. {quest:7065} needs level 45."] = "Au nord par la route jusqu'à l'avant-poste elfe de la nuit. La quête de {npc:11715} ne se partage pas : chaque joueur la prend ici, avec sa {item:17693}. {quest:7065} demande le niveau 45.",
		["On the orange side, by the Vylestem Vines: use the {item:17696} near one, a {npc:13696} comes out (45, immune to Nature); kill it to heal the vine, 8 times. Noxxion, at the end of this side, drops the {item:17702}."] = "Du côté orange, près des Vylestem Vines : utiliser la {item:17696} près de l'une d'elles, une {npc:13696} en sort (niveau 45, insensible à la Nature) ; la tuer guérit la vigne, 8 fois. Noxxion, au bout de ce côté, lâche le {item:17702}.",
		["Out of the caves, south through the Valley of Bones to the Forlorn Gardens: pour the water on Woodwyrd, then hand it in. No {item:258296}? Skip this step: {quest:93404} waits for another run."] = "Hors des grottes, au sud par la Vallée des Ossements jusqu'aux Forlorn Gardens : verser l'eau sur Woodwyrd, puis rendre la quête. Pas de {item:258296} ? Passer cette étape : {quest:93404} attend une autre visite.",
		["Ride north out of {zone:2652} through the Valley of Bones and on along the road to Kormek's Hut, by Thunder Axe Fortress: {npc:13656} waits there."] = "Sortir de {zone:2652} vers le nord par la Vallée des Ossements, puis suivre la route jusqu'à la hutte de Kormek, près de la forteresse Hache-Tonnerre : {npc:13656} y attend.",
		["Ride south-west to the Valley of Spears: the caves of Maraudon open in the hills west of it. {npc:13697} waits in the first cave. Fill the {item:17693} at an orange crystal pool, outside the orange portal (the right-hand path where the caves split); the blue water does not count."] = "Partir au sud-ouest vers la vallée des Lances : les grottes de Maraudon s'ouvrent dans les collines à l'ouest. {npc:13697} attend dans la première grotte. Remplir la {item:17693} à un bassin aux cristaux orange, devant le portail orange (le chemin de droite là où les grottes se séparent) ; l'eau bleue ne compte pas.",
		["The inner part's great cavern, under the falls: the {item:258296} for Woodwyrd is an object there, which every player with the quest takes. Its exact place is to check in game."] = "La grande caverne de la partie intérieure, sous la cascade : la {item:258296} pour Woodwyrd est un objet à cet endroit, que prend chaque joueur qui a la quête. Sa place exacte reste à vérifier en jeu.",
		["Woodwyrd"] = "Woodwyrd",
		["Woodwyrd extinguished"] = "Woodwyrd éteint",
		["Woodwyrd: {quest:93404}"] = "Woodwyrd : {quest:93404}",
		["{item:17696}: the orange crystal pool"] = "{item:17696} : le bassin aux cristaux orange",
		["{item:17702}: Noxxion"] = "{item:17702} : Noxxion",
		["{npc:12201} not beaten: {quest:7065} cannot be finished on this route, which does not come back to {zone:1443}. Abandon it."] = "{npc:12201} pas vaincue : {quest:7065} ne peut pas être finie sur ce parcours, qui ne revient pas en {zone:1443}. L'abandonner.",
		["{npc:12201}, for {quest:7065}"] = "{npc:12201}, pour {quest:7065}",
		["{npc:12201}, the last boss (51), at the far end of the inner part. {npc:12238} then rises: its quest, {quest:7066}, goes to {npc:11832} in {zone:1450}; keep it until the route passes there, around 53 on the way to {zone:1452}."] = "{npc:12201}, le dernier boss (51), tout au fond de la partie intérieure. {npc:12238} se lève ensuite : sa quête, {quest:7066}, va à {npc:11832} au {zone:1450} ; la garder jusqu'au passage du parcours, vers 53, sur le chemin du {zone:1452}.",
		["{npc:13696}: one per vine"] = "{npc:13696} : une par vigne",
		["{zone:2652}: Woodwyrd"] = "{zone:2652} : Woodwyrd",
} end)()
t.guides["groupe-alliance/monastere-ecarlate"] = (function() return {
		["Back to {npc:264265}"] = "Retour vers {npc:264265}",
		["Before entering the Scarlet Monastery"] = "Avant d'entrer dans le Monastère écarlate",
		["Clear the chapel's pews first: pulling Mograine brings the whole room. Mograine first; when he falls, Whitemane runs in, puts the group to sleep and raises him once: kill him again, then her."] = "Vider d'abord les bancs de la chapelle : attaquer Mograine attire toute la salle. Mograine d'abord ; quand il tombe, Blanchetête accourt, endort le groupe et le relève une fois : le tuer de nouveau, puis elle.",
		["Dungeon · The Scarlet Monastery (34-46)"] = "Donjon · Le Monastère écarlate (34-46)",
		["In the log before going in: {quest:1053} (Raleigh, Southshore) and {quest:96800} ({npc:264265}, Alterac); {quest:1050} too for whoever took it from Mae Paledust in {zone:1455}. Share each quest with the group: click it in the quest log, then Share."] = "Dans le journal avant d'entrer : {quest:1053} (Raleigh, Austrivage) et {quest:96800} ({npc:264265}, Alterac) ; {quest:1050} aussi pour qui l'a prise auprès de Mae Paledust à {zone:1455}. Partager chaque quête avec le groupe : clic sur la quête dans le journal, puis Partager.",
		["Loksey and his dogs wait in a small alcove near the start. Doan is the last boss: at half health he shields himself and blows up everything near him, run out and come back. The red book for {npc:264265} is on a table on the right of Doan's room; {quest:1050}, for whoever took it in {zone:1455}, on the floor of a Library corridor, under a window; the Scarlet Key, for the Armory and Cathedral doors, in the chest behind him."] = "Loksey et ses chiens attendent dans une petite alcôve près de l'entrée. Doan est le dernier boss : à mi-vie, il se protège puis fait exploser tout ce qui l'entoure, sortir de la zone puis revenir. Le livre rouge pour {npc:264265} est sur une table à droite de la salle de Doan ; {quest:1050}, pour qui l'a prise à {zone:1455}, par terre dans un couloir de la Bibliothèque, sous une fenêtre ; la clé écarlate, pour les portes de l'Armurerie et de la Cathédrale, dans le coffre derrière lui.",
		["Mages on {npc:6548}'s chain: the book of {item:7274}, for Tabetha, is in the Library too."] = "Mages sur la suite de {npc:6548} : le livre de {item:7274}, pour Tabetha, est lui aussi dans la Bibliothèque.",
		["On the way north: he stands on the western edge of the Dalaran crater, by the road from Hillsbrad to Silverpine."] = "En route vers le nord : il se tient sur le bord ouest du cratère de Dalaran, près de la route de Hautebrande à Pins-Argentés.",
		["Ride through {zone:1421}, then east across {zone:1420}: Horde land, keep clear of Brill and the guards on the roads. The monastery stands in the far north-east; the four wings are four doors in the courtyard."] = "Traverser {zone:1421}, puis {zone:1420} vers l'est : terre de la Horde, rester loin de Brill et des gardes sur les routes. Le monastère est tout au nord-est ; les quatre ailes sont quatre portes dans la cour.",
		["Scarlet Monastery"] = "Monastère Écarlate",
		["Southshore rewards"] = "Récompenses à Austrivage",
		["Southshore: {npc:3980}"] = "Austrivage : {npc:3980}",
		["The Armory: {npc:3975}"] = "L'Armurerie : {npc:3975}",
		["The Cathedral: Mograine and Whitemane"] = "La Cathédrale : Mograine et Blanchetête",
		["{item:273169}, red book on a table in Doan's room"] = "{item:273169}, livre rouge sur une table dans la salle de Doan",
		["{npc:264265}: {quest:96800}, {npc:6487}'s book"] = "{npc:264265} : {quest:96800}, livre de {npc:6487}",
		["{npc:3974}, elite 34"] = "{npc:3974}, élite 34",
		["{npc:3975} spins with Whirlwind: everyone but the tank steps away until it ends. When he dies, a wave of trainees runs in: fight them at the door."] = "{npc:3975} tourne sur lui-même avec Tourbillon : tout le monde sauf le tank s'écarte jusqu'à la fin. À sa mort, une vague de recrues accourt : les combattre à la porte.",
		["{npc:3975}, elite 40"] = "{npc:3975}, élite 40",
		["{npc:3976}, elite 42"] = "{npc:3976}, élite 42",
		["{npc:3977}, elite 42"] = "{npc:3977}, élite 42",
		["{npc:3980}, upstairs in the inn"] = "{npc:3980}, à l'étage de l'auberge",
		["{npc:3980}, upstairs in the inn: four Scarlet bosses"] = "{npc:3980}, à l'étage de l'auberge : quatre boss écarlates",
		["{npc:3980}: {quest:1052}, from {npc:1182}"] = "{npc:3980} : {quest:1052}, de {npc:1182}",
		["{npc:6487}, elite 37"] = "{npc:6487}, élite 37",
		["{quest:1050}, on the floor of a corridor: for {npc:3979} in {zone:1455}, taken on the Uldaman chapter's way"] = "{quest:1050}, par terre dans un couloir : pour {npc:3979} à {zone:1455}, prise sur le chemin du chapitre d'Uldaman",
} end)()
t.guides["groupe-alliance/souilles-de-tranchebauge"] = (function() return {
		["Back to Ratchet"] = "Retour à Cabestan",
		["Boat to Ratchet"] = "Bateau pour Cabestan",
		["Dungeon · Razorfen Downs (39-45)"] = "Donjon · Souilles de Tranchebauge (39-45)",
		["Fly to {zone:1453}"] = "Prendre un vol pour {zone:1453}",
		["Last stop of the chapter: the route's own guide comes back once this is handed in."] = "Dernier arrêt du chapitre : le guide du parcours revient une fois cette quête rendue.",
		["Polestar asks whether to do this escort: in a group, answer Do it (Skip it takes the quest out of the chapter)."] = "Polestar demande s'il faut faire cette escorte : en groupe, répondre « La faire » (« La passer » retire la quête du chapitre).",
		["Protect him at the idol"] = "Le protéger à l'idole",
		["Razorfen Downs"] = "Souilles de Tranchebauge",
		["Razorfen Downs: the quilboar and Scourge barrows at the southern edge of the {zone:1413}, for a group of 5, levels 37 to 46: at 41 it fits. {npc:1284} stands in the Cathedral of Light. {quest:3636} cannot be shared: every player takes it here."] = "Les Souilles de Tranchebauge : les terriers des huranes et du Fléau au sud des {zone:1413}, pour un groupe de 5, niveaux 37 à 46 : à 41, c'est le bon moment. {npc:1284} se tient dans la Cathédrale de la Lumière. {quest:3636} ne se partage pas : chaque joueur la prend ici.",
		["Razorfen Downs: {npc:12866}"] = "Souilles de Tranchebauge : {npc:12866}",
		["Razorfen Downs: {npc:7358}"] = "Souilles de Tranchebauge : {npc:7358}",
		["Razorfen Downs: {npc:8516}"] = "Souilles de Tranchebauge : {npc:8516}",
		["Share nothing here: each player talks to {npc:8516}."] = "Rien à partager ici : chaque joueur parle à {npc:8516}.",
		["The last boss (elite 41), at the far end: he casts frost novas and calls frozen spectres; keep the healer out of his reach."] = "Le dernier boss (élite 41), tout au fond : il lance des novas de givre et appelle des spectres gelés ; garder le soigneur hors de sa portée.",
		["The road south"] = "La route du sud",
		["{npc:1284}, in the Cathedral of Light"] = "{npc:1284}, dans la Cathédrale de la Lumière",
		["{npc:12866} waits on a hill outside the dungeon. Her quest is the group quest the route offered at 32: the answer given then counts here too, and whoever did it then has nothing to take. The three targets live outside the portal, among the barrows and thorns (elites, 33)."] = "{npc:12866} attend sur une colline devant le donjon. Sa quête est la quête de groupe que le parcours a proposée vers 32 : la réponse donnée alors vaut aussi ici, et qui l'a faite alors n'a rien à prendre. Les trois cibles vivent devant le portail, parmi les terriers et les épines (élites, 33).",
		["{npc:12866}, on a hill outside"] = "{npc:12866}, sur une colline devant le donjon",
		["{npc:8516} waits in a prison cell inside. His quests cannot be shared: every player takes {quest:3523} and hands it in to him (he wants his Oathstone back) BEFORE anyone starts {quest:3525}. Then he walks to the idol and casts while waves of enemies come: stay close and keep them off him; it ends at his brazier."] = "{npc:8516} attend dans une cellule à l'intérieur. Ses quêtes ne se partagent pas : chaque joueur prend {quest:3523} et la lui rend (il veut récupérer sa pierre de serment) AVANT que quiconque lance {quest:3525}. Il marche alors jusqu'à l'idole et incante pendant que des vagues d'ennemis arrivent : rester près de lui et les tenir loin ; cela finit à son brasero.",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
} end)()
t.guides["groupe-alliance/temple-englouti"] = (function() return {
		["Dungeon · The Sunken Temple (50-56)"] = "Donjon · Le temple englouti (50-56)",
		["Group of 5. Keep 4 free quest log slots. In the quest log before going in: {quest:1475} ({npc:5384}, {zone:1453}); for whoever took them at the Broken Pillar in {zone:1446}, {quest:3446} and {quest:3447} ({npc:7771}). Share each one with the group: click it in the quest log, then Share."] = "Groupe de 5. Garder 4 places libres dans le journal. Dans le journal avant d'entrer : {quest:1475} ({npc:5384}, {zone:1453}) ; pour qui les a prises au Pilier Brisé en {zone:1446}, {quest:3446} et {quest:3447} ({npc:7771}). Partager chacune avec le groupe : clic sur la quête dans le journal, puis Partager.",
		["On the upper ring, six Atal'ai statues stand around the central pit: click them in this order, south, north, south-west, south-east, north-west, north-east (the original game's order, to check in game); the {object:148838} rises, with a chest. The {object:148836} is at the bottom of the central pit, where {npc:8580} waits."] = "Sur l'anneau supérieur, six statues atal'ai entourent la fosse centrale : les cliquer dans cet ordre, sud, nord, sud-ouest, sud-est, nord-ouest, nord-est (l'ordre du jeu d'origine, à vérifier en jeu) ; l'{object:148838} apparaît, avec un coffre. L'{object:148836} est au fond de la fosse centrale, où attend {npc:8580}.",
		["Out of the {zone:1435} to Nethergarde Keep, then the flight to {zone:1453}. Last stop of the chapter: the route's own guide comes back once this is handed in; its next stop, {zone:1455}, is a ride on the Deeprun Tram."] = "Sortir du {zone:1435} vers Rempart-du-Néant, puis le vol pour {zone:1453}. Dernier arrêt du chapitre : le guide du parcours revient une fois cette quête rendue ; son arrêt suivant, {zone:1455}, est à un trajet du Tram des profondeurs.",
		["Ride north out of the {zone:1419} into the {zone:1435}, then east past Stonard (Horde) to the Pool of Tears. The temple lies under the water: swim down into it and find the dungeon's entrance inside."] = "Sortir des {zone:1419} par le nord vers le {zone:1435}, puis aller à l'est après Pierrêche (Horde) jusqu'au Bassin des larmes. Le temple est sous l'eau : plonger, entrer et trouver l'entrée du donjon à l'intérieur.",
		["Sunken Temple"] = "Temple englouti",
		["Sunken Temple: the Pool of Tears"] = "Temple englouti : le Bassin des larmes",
		["Sunken Temple: the circle and the {object:148836}"] = "Temple englouti : le cercle et l'{object:148836}",
		["Sunken Temple: the tablets and Jammal'an"] = "Temple englouti : les tablettes et Jammal'an",
		["Sunken Temple: the {npc:5709}"] = "Temple englouti : {npc:5709}",
		["The Atal'ai Tablets lie in the temple's halls: pick them up as you clear. {npc:5710} waits on the upper level, once the six troll champions of the balconies around the central pit are dead."] = "Les tablettes atal'ai sont dans les salles du temple : les ramasser en avançant. {npc:5710} attend au niveau supérieur, une fois tués les six champions trolls des balcons qui entourent la fosse centrale.",
		["The Sunken Temple: a troll and dragon dungeon under the Pool of Tears in the {zone:1435}, levels 50 to 60, best from about 52 with a group of 5: its last bosses are 55. Its main quest is {npc:5384}'s, in {zone:1453}: from Nethergarde Keep, the flight to {zone:1453} and back, about 7 minutes."] = "Le temple englouti : un donjon de trolls et de dragons sous le Bassin des larmes, dans le {zone:1435}, niveaux 50 à 60, idéal à partir de 52 environ en groupe de 5 : ses derniers boss sont de niveau 55. Sa quête principale est celle de {npc:5384}, à {zone:1453} : depuis Rempart-du-Néant, le vol pour {zone:1453} et retour, environ 7 minutes.",
		["The {npc:5709} waits at the very end, past the green dragons. He drops the {item:10454}: right-click it, then hand it in at the {object:148512} in his room before leaving."] = "{npc:5709} attend tout au fond, après les dragons verts, et laisse l'{item:10454} : clic droit dessus, puis la rendre au {object:148512}, dans la même salle, avant de partir.",
		["{item:10454}, a drop"] = "{item:10454}, un butin",
		["{object:148836}, in the temple's lowest hall: {quest:3446}, from {npc:7771}"] = "{object:148836}, dans la salle la plus basse du temple : {quest:3446}, de {npc:7771}",
		["{object:148838}: {quest:3447}, from {npc:7771} at the Broken Pillar in {zone:1446}"] = "{object:148838} : {quest:3447}, de {npc:7771} au Pilier Brisé en {zone:1446}",
} end)()
t.guides["groupe-alliance/uldaman"] = (function() return {
		["Both stand in the {object:32356}. Karnik's last task, An Ambassador of Evil, leads to a second Uldaman run, not in this guide: do not take it. Last stop of the chapter: the route's own guide comes back where it was, in {zone:1453}: it has the class trainer visited there first (the Deeprun Tram from {object:171524}, or the flight), then flies on to Thelsamar for the {zone:1418}."] = "Tous deux se tiennent dans {object:32356}. La dernière tâche de Karnik, An Ambassador of Evil, mène à un second passage à Uldaman, hors de ce guide : ne pas la prendre. Dernier arrêt du chapitre : le guide du parcours revient où il en était, à {zone:1453} : il fait d'abord passer chez le maître de classe là-bas (le tram des profondeurs depuis {object:171524}, ou le vol), puis vole vers Thelsamar pour les {zone:1418}.",
		["Dungeon · Uldaman (42-48)"] = "Donjon · Uldaman (42-48)",
		["Explore the hidden chamber"] = "Explorer la chambre cachée",
		["Fly to Thelsamar"] = "Vol pour Thelsamar",
		["Fly to {zone:1455}"] = "Vol pour {zone:1455}",
		["For {npc:2910}, on the way out of the {zone:1418}"] = "Pour {npc:2910}, en sortant des {zone:1418}",
		["For {npc:2916} in {zone:1455}"] = "Pour {npc:2916} à {zone:1455}",
		["Keep 6 free quest log slots. Everyone takes the quests at their own pace; meet at the dungeon's door for the run."] = "Garder 6 places libres dans le journal. Chacun prend les quêtes à son rythme ; rendez-vous à la porte du donjon pour la partie.",
		["Leave by the front, south to the Valley of Fangs."] = "Sortir par l'entrée, au sud vers la Vallée des Crocs.",
		["Mages: {quest:1956}"] = "Mages : {quest:1956}",
		["On the way back north to the pass into {zone:1432} and the Thelsamar flight."] = "Sur le chemin du retour vers le nord, vers le col du {zone:1432} et le vol de Thelsamar.",
		["Ride south through the pass into the {zone:1418}. Ryedol's errand left at the start of the route's {zone:1418} visit, {quest:720}, now serves Uldaman: it sends you to {npc:2909}, just outside the dungeon."] = "Descendre au sud par le col dans les {zone:1418}. La mission de Ryedol laissée au début du passage du parcours dans les {zone:1418}, {quest:720}, sert maintenant Uldaman : elle envoie vers {npc:2909}, juste devant le donjon.",
		["Share each quest with your group: click it in the quest log, then Share. A {item:7666} may drop on the way: its chain goes on with {npc:6826} in {zone:1455}."] = "Partager chaque quête avec le groupe : cliquer dessus dans le journal, puis Partager. Un {item:7666} peut tomber en route : sa suite continue avec {npc:6826} à {zone:1455}.",
		["The Shadowforge dwarves of the digsite in front of the cave and of the outer cave drop both power stones, not often: no need to enter the instance for them. {npc:6294}'s chest is in the outer cave, at the back of the left-hand hall, behind a pillar, with two guards."] = "Les nains Ombreforge du site de fouilles devant la grotte et de la grotte extérieure lâchent les deux pierres de pouvoir, rarement : pas besoin d'entrer dans l'instance pour elles. Le coffre de {npc:6294} est dans la grotte extérieure, au fond du couloir de gauche, derrière un pilier, avec deux gardes.",
		["The digsite and the outer cave"] = "Le site de fouilles et la grotte extérieure",
		["Thelsamar flight master"] = "Maître de vol de Thelsamar",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Uldaman"] = "Uldaman",
		["Uldaman: a dwarf and titan dungeon at the north end of the {zone:1418}, for a group of 5, levels 41 to 51 in the group finder: best at 43 or more. Its quests start in {zone:1455}: the Deeprun Tram from the {object:28027}, then the flight to Thelsamar and south into the {zone:1418}. The rewards are handed in in {zone:1455} at the end; the flight back to Thelsamar then joins the route's {zone:1418} guide."] = "Uldaman : un donjon nain et titan au nord des {zone:1418}, pour un groupe de 5, niveaux 41 à 51 dans la recherche de groupe : idéal à 43 ou plus. Ses quêtes commencent à {zone:1455} : le Tram des profondeurs depuis {object:28027}, puis le vol pour Thelsamar et la descente au sud dans les {zone:1418}. Les récompenses se rendent à {zone:1455} à la fin ; le vol de retour vers Thelsamar rejoint ensuite le guide {zone:1418} du parcours.",
		["Uldaman: {npc:2909}"] = "Uldaman : {npc:2909}",
		["Valley of Fangs: {npc:2817}"] = "Vallée des Crocs : {npc:2817}",
		["{item:4635}: {npc:2932}, elite 38"] = "{item:4635} : {npc:2932}, élite 38",
		["{item:7666}, a drop: for {npc:6826} in {zone:1455}"] = "{item:7666}, un butin : pour {npc:6826} à {zone:1455}",
		["{item:8009}: Shadowforge dwarves"] = "{item:8009} : nains Ombreforge",
		["{item:8027}, from his chest"] = "{item:8027}, dans son coffre",
		["{item:8052}: Shadowforge dwarves"] = "{item:8052} : nains Ombreforge",
		["{npc:1356}, {npc:6294} and {npc:3979} all stand in the {object:32356}. Mae Paledust's quest is for the Scarlet Monastery ({npc:3980}, Southshore): take it only if your group has not run it yet and still plans to."] = "{npc:1356}, {npc:6294} et {npc:3979} se tiennent tous dans {object:32356}. La quête de Mae Paledust est pour le Monastère écarlate ({npc:3980}, Austrivage) : la prendre seulement si le groupe ne l'a pas encore fait et compte le faire.",
		["{npc:1356}, {npc:6294} and {npc:5387} are all in the {object:32356}; {npc:6826} in the {object:32362}."] = "{npc:1356}, {npc:6294} et {npc:5387} sont tous dans {object:32356} ; {npc:6826} dans {object:32362}.",
		["{npc:2817}'s {quest:2418} drop from the Shadowforge dwarves at Uldaman's door, not often: worth it only for a group that means to farm them a little. Otherwise skip it."] = "Les pierres de {npc:2817} ({quest:2418}) tombent des nains Ombreforge à la porte d'Uldaman, pas souvent : utile seulement pour un groupe prêt à en chercher un peu. Sinon, la passer.",
		["{npc:2817}, Valley of Fangs"] = "{npc:2817}, Vallée des Crocs",
		["{npc:2909} waits just outside Uldaman, west of the cave. His amulet is on {npc:2932}, a Shadowforge dwarf (elite 38) outside the dungeon portal, south of {npc:2909}."] = "{npc:2909} attend juste devant Uldaman, à l'ouest de la grotte. Son amulette est sur {npc:2932}, un nain Ombreforge (élite 38) devant le portail du donjon, au sud de {npc:2909}.",
		["{npc:2910}: for {npc:2909}, outside Uldaman"] = "{npc:2910} : pour {npc:2909}, devant Uldaman",
		["{npc:3979}: for the Scarlet Monastery"] = "{npc:3979} : pour le Monastère écarlate",
		["{npc:6826}: his follow-ups need another Uldaman run, not in this guide"] = "{npc:6826} : ses suites nécessitent un autre passage à Uldaman, pas dans ce guide",
		["{npc:6906} and the hidden chamber"] = "{npc:6906} et la chambre cachée",
		["{npc:6906}, Eric and Olaf wait in the first halls, at the top of a ramp. The chest beside {npc:6906} holds the {item:7740}, Revelosh drops the Shaft of Tsol: together they make the {item:7733}. Plant it in the Map Room, kill Ironaya (elite), then walk all the way into the chamber."] = "{npc:6906}, Eric et Olaf attendent dans les premiers couloirs, en haut d'une rampe. Le coffre près de {npc:6906} contient le {item:7740}, Revelosh lâche la hampe : ensemble ils forment le {item:7733}. Le planter dans la Salle des Cartes, tuer Ironaya (élite), puis avancer jusqu'au fond de la chambre.",
		["{npc:7292}, in the Vault"] = "{npc:7292}, dans la Chambre forte",
		["{object:32356}: {npc:2916} and {npc:2918}"] = "{object:32356} : {npc:2916} et {npc:2918}",
		["{quest:1956}, for Mages: the {npc:7023}, one of the bosses on the way to {npc:2748}, drops the {item:8053} for Tabetha in {zone:1445}."] = "{quest:1956}, pour les mages : la {npc:7023}, l'un des boss sur le chemin d'{npc:2748}, lâche la {item:8053} pour Tabetha au {zone:1445}.",
		["{zone:1453}: the Uldaman chapter"] = "{zone:1453} : le chapitre d'Uldaman",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
		["{zone:1455} rewards"] = "Récompenses à {zone:1455}",
} end)()
t.guides["groupe-alliance/zul-farrak"] = (function() return {
		["Dungeon · Zul'Farrak (45-50)"] = "Donjon · Zul'Farrak (45-50)",
		["Gadgetzan: Zul'Farrak rewards"] = "Gadgetzan : récompenses de Zul'Farrak",
		["Group of 5: share each quest (quest log, Share) before going in. {npc:7267}, the last boss, waits behind the door Weegli blows open after the pyramid event."] = "Groupe de 5 : partager chaque quête (journal de quêtes, Partager) avant d'entrer. {npc:7267}, le dernier boss, attend derrière la porte que Weegli fait sauter après l'événement de la pyramide.",
		["Keep 3 free quest log slots."] = "Garder 3 places libres dans le journal.",
		["Last stop of the chapter: the route's own guide comes back once these are handed in."] = "Dernier arrêt du chapitre : le guide du parcours revient une fois ces quêtes rendues.",
		["Ride north-west from Gadgetzan to the walled city, at the edge of the dunes. Inside, every troll can drop {quest:3042}; the scarabs by the graveyard of {npc:7272} drop the shells.\nThe pyramid event: free {npc:7604} and his crew from the cage at the top of the stairs, then hold the stairs against the troll waves. Once the trolls are dead, Bly turns on you: he drops the {quest:2768}."] = "Partir vers le nord-ouest depuis Gadgetzan jusqu'à la cité fortifiée, au bord des dunes. À l'intérieur, chaque troll peut laisser tomber {quest:3042} ; les scarabées près du cimetière de {npc:7272} laissent tomber les carapaces.\nL'événement de la pyramide : libérer {npc:7604} et son équipe de la cage en haut des marches, puis tenir les marches contre les vagues de trolls. Une fois les trolls morts, Bly se retourne contre le groupe : il laisse tomber {quest:2768}.",
		["Zul'Farrak"] = "Zul'Farrak",
		["Zul'Farrak: Gadgetzan"] = "Zul'Farrak : Gadgetzan",
		["Zul'Farrak: a troll city in the north-west of {zone:1446}, levels 44 to 54, best at 45 or more with a full group. Three quests from Gadgetzan, all done inside: {npc:7876} on the north side of town, {npc:7804} and {npc:7407} by the water tower."] = "Zul'Farrak : une cité troll au nord-ouest de {zone:1446}, niveaux 44 à 54, idéale à partir de 45 en groupe complet. Trois quêtes à Gadgetzan, toutes faites à l'intérieur : {npc:7876} au nord de la ville, {npc:7804} et {npc:7407} près du château d'eau.",
		["{npc:7795} holds the courtyard of the great pool, round the corner from the entrance: whoever took Tabetha's {item:9234} in {zone:1445} finds the tiara on her. A rare {item:8623} can drop here, as from most of the creatures of {zone:1446}: the guide does not follow it."] = "{npc:7795} tient la cour du grand bassin, après le coin de l'entrée : qui a pris la quête de Tabetha, {item:9234}, en {zone:1445} trouve la tiare sur elle. Une rare {item:8623} peut tomber ici, comme de la plupart des créatures de {zone:1446} : le guide ne la suit pas.",
} end)()
t.guides["groupe-alliance/zul-farrak-2"] = (function() return {
		["A second Zul'Farrak run for {quest:2770}, the boss of the sacred pool: 14,600 XP and the {item:11122}, a trinket that speeds up a mount. One player of the group needs the {item:9240}, made in the {zone:1425} (the {item:9241} from {npc:7996} at the top of the Altar of Zul, used on the altar at the very top of Jintha'Alor). Nobody in the group has it? Skip it: {quest:2770} cannot be called, and the chapter closes."] = "Un second passage à Zul'Farrak pour {quest:2770}, le boss du bassin sacré : 14 600 XP et la {item:11122}, un bijou qui accélère la monture. Un joueur du groupe doit avoir le {item:9240}, fait dans les {zone:1425} (le {item:9241} pris sur {npc:7996} au sommet de l'autel de Zul, utilisé sur l'autel tout en haut de Jintha'Alor). Personne dans le groupe ne l'a ? La passer : {quest:2770} ne peut pas être appelé, et le chapitre se ferme.",
		["Back north to the Mirage Raceway. Last stop of the chapter: the route's own guide comes back once this is handed in, at Gadgetzan."] = "Retour au nord vers le circuit de Mirage. Dernier arrêt du chapitre : le guide du parcours revient une fois cette quête rendue, à Gadgetzan.",
		["Dungeon · Zul'Farrak, second run (49-53)"] = "Donjon · Zul'Farrak, second passage (49-53)",
		["Mirage Raceway: {npc:4453}"] = "Circuit de Mirage : {npc:4453}",
		["Ride south-west to the walled city: the trolls are below you now, about an hour with a group of 5. {quest:2770}'s pool is in {npc:7795}'s courtyard, round the corner from the entrance. The player with the {item:9240} uses it on the gong by the pool; {quest:2770} rises from the water and throws players into the air: fight him in the pool, or under the ruin left of the archway, to soften the falls."] = "Partir au sud-ouest vers la cité fortifiée : les trolls sont maintenant de plus bas niveau, environ une heure en groupe de 5. Le bassin de {quest:2770} est dans la cour de {npc:7795}, après le coin de l'entrée. Le joueur qui a le {item:9240} l'utilise sur le gong près du bassin ; {quest:2770} sort de l'eau et projette les joueurs en l'air : le combattre dans le bassin, ou sous la ruine à gauche de l'arche, pour amortir les chutes.",
		["Share {quest:2770} with the group before going in: click it in the quest log, then Share."] = "Partager {quest:2770} avec le groupe avant d'entrer : clic sur la quête dans le journal, puis Partager.",
		["Zul'Farrak"] = "Zul'Farrak",
		["Zul'Farrak, second run: {npc:4453}"] = "Zul'Farrak, second passage : {npc:4453}",
		["Zul'Farrak: {quest:2770}"] = "Zul'Farrak : {quest:2770}",
		["{item:9240}, at the gong"] = "{item:9240}, au gong",
} end)()

Polestar.RegisterGuideTexts("frFR", "groupe-alliance", t)
